window.BOOK={"key":"usul","app":"mutoon","lsk":"mutoon_usul_v2","title":"تهذيب مسار الأصول","sub":"إلى علم أصول فقه الحنفية · أ.د. صلاح محمد أبو الحاج · التعريفات والقواعد","unitWord":"معلومة","sharhDir":"data/usul-sharh/","study":"qa","chapters":[{"id":"u3","title":"المطلب الأول: تعريف علم أصول الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u3_1","label":"تعريف العلم","segs":[["matn","العلم: نقيض الجهل، وهو معرفة الشيء على ما هو به والمعنى الحقيقي للعلم: هو الإدراك."]],"q":"ما تعريف العلم؟ وما معناه الحقيقي؟"},{"id":"u3_2","label":"الأصل لغةً","segs":[["matn","أصول: لغةً: جمع أصل، وهو أسفلُ كلُّ شيء، وأساسه، فمدارُ معنى الأصل لغةً فيما يُبتني عليه غيره"]],"q":"ما معنى الأصل لغةً؟"},{"id":"u3_3","label":"معاني الأصل اصطلاحًا","segs":[["matn","الأصل: واصطلاحاً: وله معان، وهي: ١. الدَّليل ٢. الرَّاجح ٣. المستصحب ٤. القاعدة"]],"q":"ما معاني الأصل اصطلاحًا؟"},{"id":"u3_4","label":"الفقه لغةً","segs":[["matn","الفقه: لغةً: هو الفهم مطلقاً"]],"q":"ما معنى الفقه لغةً؟"},{"id":"u3_5","label":"تعريف الفقه عند الحنفية","segs":[["matn","الفقه: معرفةُ النَّفسِ ما لها وما عليها عملاً. ومعنى ما لها وما عليها: ما يجوز لها، وما يحرم عليها"]],"q":"ما تعريف الفقه عند الحنفية؟ وما معنى ما لها وما عليها؟"},{"id":"u3_6","label":"تعريف الفقه عند الشافعية","segs":[["matn","الفقه: العلم بالأحكام الشَّرعيَّة العملية المكتسب من أدلتها التَّفصيليَّة."]],"q":"ما تعريف الفقه عند الشافعية؟"},{"id":"u3_7","label":"تعريف أصول الفقه لقبًا","segs":[["matn","أصول الفقه: ١. أدلة إجمالية للفقه يُحتاج إليها عند تطبيق الأدلة التَّفصيلية على أحكامها. ٢. العلمُ بالقواعدِ التي يتوصَّل بها إلى استنباطِ الأحكام الشَّرعيّة الفرعيّة من أدلتها التَّفصيلية."]],"q":"ما تعريفا أصول الفقه لقبًا؟"}],"sup":"المبحثُ الأوّل تعريف علم الأصول والتَّفريق بينه وبين علم الفقه"},{"id":"u4","title":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u4_1","label":"الفرق في الغاية","segs":[["matn","إنَّ الغاية من الأصول إجمالاً هي معرفة الأحكام من أدلتها التَّفصيلية، أما الفقه فغايته الفوز بسعادة الدَّارين باتباع الأوامر واجتناب النَّواهي"]],"q":"ما الفرق بين الأصول والفقه من حيث الغاية؟"},{"id":"u4_2","label":"الفرق في الموضوع","segs":[["matn","إنَّ موضوع الأصول الأدلة والأحكام بينما موضوع الفقه أَفعال العباد من حيث ما ثبت لها من أحكام شرعية."]],"q":"ما الفرق بين الأصول والفقه من حيث الموضوع؟"},{"id":"u4_3","label":"وظيفة الفقيه ووظيفة الأصولي","segs":[["matn","وظيفة الفقيه بيان الحكم بغض النَّظر عن دليله، ووظيفة الأصولي بيان دليل كلِّ مسأَلة فقهية"]],"q":"ما الفرق بين وظيفة الفقيه ووظيفة الأصولي؟"}],"sup":"المبحثُ الأوّل تعريف علم الأصول والتَّفريق بينه وبين علم الفقه"},{"id":"u6","title":"المطلب الأوّل: أصول الفقه في العهد النَّبوي","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u6_1","label":"اجتهاد النبي عند الحنفية","segs":[["matn","والمختار عند الحنفية المتأخرين: أنَّه ﷺ مأمور في حادثة لا وحي فيها بانتظار الوحي أولاً ما كان راجي الوحي إلى خوف فوت الحادثة بلا حكم، ثم بالاجتهاد ثانياً إذا مضى وقت الانتظار على حسب الحادثة ولم يوح إليه"]],"q":"ما المختار عند الحنفية المتأخرين في اجتهاد النبي ﷺ؟"},{"id":"u6_2","label":"حكم إقرار اجتهاده ﷺ","segs":[["matn","فإن أُقر ﷺ على ما أدى إليه اجتهاده عند خوف الحادثة، أَوجب إقراره عليه القطع بصحة ما أدّى إليه اجتهاده؛ لأنَّه لا يُقرّ على الخطأ، فلم يجز مخالفته كالنَّص"]],"q":"ما حكم ما أُقرّ عليه ﷺ من اجتهاده؟ ولماذا؟"},{"id":"u6_3","label":"مجال اجتهاده ﷺ","segs":[["matn","والاجتهاد في حقّه ﷺ يختصُّ بالقياس"]],"q":"بمَ يختص الاجتهاد في حقّه ﷺ؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u7","title":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u7_1","label":"أصول اجتهاد الصحابة","segs":[["matn","ومن الأمثلة على الأصول التي استندوا لها في اجتهاداتهم: ١. مراتب الأدلة في استخراج الأحكام ٢. التَّعارض والتَّرجيح ٣. النَّسخ ٤. الإجماع ٥. القياس ٦. دوران الحكم مع علَّته"]],"q":"ما أمثلة الأصول التي استند إليها الصحابة في اجتهاداتهم؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u8","title":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u8_1","label":"أصل مدرستي المدينة والكوفة","segs":[["matn","أنَّ أبرز مدرستين فقهيتين تَكَوَنتا في عصر التَّابعين في المدينة والكوفة كان من أصولهما: الاعتماد على الفقه الموروث عن مشايخهم من كبار التَّابعين والصَّحابة"]],"q":"ما الأصل الذي اعتمدته مدرستا المدينة والكوفة في عصر التابعين؟"},{"id":"u8_2","label":"الاعتماد على المرسل","segs":[["matn","ومن الأصول التي عوِّل عليها في عصر التَّابعين الاعتماد على الحديث المرسل، إذ قبلوا الخبر المرسل كالخبر المسند إذا كان مُرسله ثقة"]],"q":"ما حكم الحديث المرسل عند التابعين؟ ومتى قبلوه؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u9","title":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين»","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u9_1","label":"تقدم تدوين الفقه","segs":[["matn","وقد دُوِّنَ الفقه الإسلامي وَهُذِّبت أبوابه قبل أن يُدَوَّن علم الأصول."]],"q":"أيهما دُوِّن أولًا: الفقه أم علم الأصول؟"},{"id":"u9_2","label":"أول تدوين في الأصول","segs":[["matn","وقد نُسب أول تدوين في أصول الفقه إلى أبي يوسف رضي الله عنه؛ إذ ألَّف في أصول أبي حنيفة رضي الله عنه فأول كتاب مستقل في الأصول يصل إلينا هو كتاب الشَّافعيّ المسمَّى بـ: «الرِّسالة»"]],"q":"إلى مَن نُسب أول تدوين في الأصول؟ وما أول كتاب مستقل وصلنا؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u10","title":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب»","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u10_1","label":"تعريف طريقة الفقهاء","segs":[["matn","طريقة الفقهاء: وامتازت هذه الطَّريقة بأَنَّ علماء الحنفية وَجَّهوا عنايتهم إلى تقرير القواعد الأصولية وتحقيقها على ضوء ما نقل عن أئمتهم من الفروع الفقهية"]],"q":"بمَ امتازت طريقة الفقهاء في الأصول؟"},{"id":"u10_2","label":"القاعدة تتبع الفرع","segs":[["matn","طريقة الفقهاء: القواعد الأصولية مستخرجة من الفروع الفقهية، فإذا تعارضت القاعدة الأصولية مع الفرع الفقهي عُدِّلت القاعدة بما يتفق مع الفرع الفقهي"]],"q":"ما علاقة القاعدة الأصولية بالفرع الفقهي عند الفقهاء؟ وماذا يُفعل عند التعارض؟"},{"id":"u10_3","label":"تقسيم الحنفية للألفاظ","segs":[["matn","طريقة الفقهاء: تقسيمهم للألفاظ كالآتي: أ. من حيث الوضوح إلى: الظَّاهر، والنَّص، والمفسَّر، والمحكم. ب. من حيث الإبهام إلى: الخفي، والمشكل، والمجمل، والمتشابه. ج. من حيث الدلالة على المعنى إلى: دلالة العبارة، ودلالة النَّص، ودلالة الإشارة، ودلالة الاقتضاء."]],"q":"ما تقسيم الحنفية للألفاظ من حيث الوضوح والإبهام والدلالة؟"},{"id":"u10_4","label":"قواعد أصولية عند الحنفية","segs":[["matn","طريقة الفقهاء: من القواعد الأصولية التي اعتمدوها: أ. عدمُ الاحتجاج بمفهوم المخالفة. ب. دلالةُ العام على أفراده قطعية. ج. عدمُ حمل المطلق على المقيد إذا اتحدا في سبب الحكم والموضوع. د. الاحتجاج بالحديث المرسل. هـ. عدم الأخذ بخبر الواحد فيما تعم به البلوى."]],"q":"ما القواعد الأصولية التي اعتمدها الحنفية؟"},{"id":"u10_5","label":"تعريف طريقة المتكلمين","segs":[["matn","طريقة المتكلمين: وتميَّزت هذه الطَّريقة بتحقيق المسائل تحقيقاً منطقياً نظرياً، وتمحيص الخلافات مع الميل إلى الاستدلال العقلي وكان يميل إلى هذه الطَّريقة علماء المالكية والشَّافعية وعلماء الكلام"]],"q":"بمَ تميّزت طريقة المتكلمين؟ ومن مال إليها؟"},{"id":"u10_6","label":"قواعد أصولية عند المتكلمين","segs":[["matn","طريقة المتكلمين: من القواعد الأصولية التي اعتمدوها: أ. الأخذ بمفهوم المخالفة. ب. دلالة العام على أفراده دلالة ظنية. ج. قَبول خبر الواحد فيما تعم به البلوى."]],"q":"ما القواعد الأصولية التي اعتمدها المتكلمون؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u11","title":"المسلك الثَّالث: طريقة المتأخرين","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u11_1","label":"تعريف طريقة المتأخرين","segs":[["matn","طريقة المتأخرين: تقوم هذه الطَّريقة على الجمع بين طريقة المتكلمين التي تقوم على تحقيق القواعد الأصولية تحقيقاً نظرياً منفصلاً عن الفقه، وعلى طريقة الفقهاء التي تقوم على تحقيق القواعد الأصولية تحقيقاً مرتبطاً بالفقه ومعتمداً عليه"]],"q":"على أي شيء تقوم طريقة المتأخرين في الأصول؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u12","title":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u12_1","label":"تعريف طريقة التخريج","segs":[["matn","طريقة تخريج الفروع على الأصول: إنَّ التَّأليف على هذه الطَّريقة لا يعتبر تأليفاً في الأصول المحضة، ولا في الفروع المحضة، وإنَّما هو مزيج من الأصول والفروع لبيان أثر الأصول في الفروع"]],"q":"ما حقيقة التأليف على طريقة تخريج الفروع على الأصول؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u13","title":"المسلك الخامس: طريقة المعاصرين","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u13_1","label":"تعريف طريقة المعاصرين","segs":[["matn","طريقة المعاصرين: وتقوم على الجمع والتَّلفيق في الأصول والفروع بين جميع المذاهب الفقهيّة دون اتباع منهج صحيح واضح؛ إذ نَقلت علم الأصول من العلميّة إلى الثَّقافية."]],"q":"على أي شيء تقوم طريقة المعاصرين؟ وما أثرها في علم الأصول؟"}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u15","title":"المطلب الأول: موضوع علم أصول الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u15_1","label":"تعريف موضوع الأصول","segs":[["matn","موضوع علم أصول الفقه: الدَّليل السَّمعي الكلي من حيث يوصل العلم بأحواله إلى قدرة إثبات الأحكام لأفعال المكلفين"]],"q":"ما موضوع علم أصول الفقه؟"},{"id":"u15_2","label":"تفصيل موضوع الأصول","segs":[["matn","وبيان ذلك أنَّ موضوعه: ١. الأدلة الشَّرعية من حيث ذاتها: أي من حيث كونها حجة قطعاً أو ظنَّاً، وغير حجة. ٢. ما يثبت من الأدلة الشَّرعية من الأحكام ٣. طرق الاستنباط من الأدلة الشَّرعية ٤. المُستَنْبِط من الأدلة الشَّرعية: أي المجتهد."]],"q":"ما تفصيل موضوع علم أصول الفقه؟"}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u16","title":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u16_1","label":"مصادر استمداد الأصول","segs":[["matn","يستمد علم الأصول من الكلام والعربية والأحكام الشرعية من جهة تصورها لا من جهة العلم بثبوتها"]],"q":"مِمَّ يُستمدّ علم الأصول؟"},{"id":"u16_2","label":"استقلال علم الأصول","segs":[["matn","فظهر أنَّ هذا العلم مستقل برأسه غير مستمد من علم مدون قبله."]],"q":"هل علم الأصول مستمد من علم مدوّن قبله؟"}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u17","title":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u17_1","label":"فوائد علم الأصول","segs":[["matn","فائدة علم أصول الفقه: ١. القدرة على معرفة الأحكام الشَّرعيّة من أدلتها ٢. إنَّ للأصول أثراً في تكوين العقلية الفقهيّة القادرة على الدَّرس والفحص والاستنباط السَّليم ٣. إنَّه من أكثر وسائل حفظ الدِّين وصون أدلته وحججه من شُبه المتحلِّلين وتضليل الملحدين ٤. إننا نتعرَّف بواسطة قواعد الأصول مدارك الفقهاء المجتهدين وطرق استنباطهم"]],"q":"ما فوائد علم أصول الفقه؟"}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u18","title":"المطلب الرَّابع: حكم تعلم علم أصول الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u18_1","label":"حكم تعلم الأصول","segs":[["matn","إنَّ تعلم علم الأصول كأغلب العلوم النَّافعة الشَّرعية وغير الشَّرعية واجبٌ على الكفاية، فإن قامَ به البعض سقط عن الباقين"]],"q":"ما حكم تعلم علم الأصول؟"},{"id":"u18_2","label":"الاستحباب والإباحة والتحريم","segs":[["matn","ويستحبُّ تَعَلُّمه للمسلمين كباقي العلوم وإن قام به بعضهم أمّا إن تَعَلَّمه للزِّينة والكمال فهو مباحٌ ويحرم تَعَلُّمه إن كان ليباهي به العلماء، ويماري به السُّفهاء، ويأكل به أموال الأغنياء، ويستخدم به الفقراء"]],"q":"متى يُستحب تعلم الأصول؟ ومتى يُباح؟ ومتى يحرم؟"}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u21","title":"أولاً: معنى الدَّليل","group":"الباب الثَّاني الكتاب","units":[{"id":"u21_1","label":"تعريف الدليل","segs":[["matn","فالدَّليل لغةً: ما يستدلُّ به، وأيضاً: الدَّالّ، وقيل: الدَّليل: هو المُرشد. واصطلاحاً: ما يمكن التَّوصل بصحيح النَّظر فيه إلى مطلوب خبري."]],"q":"ما تعريف الدليل لغةً واصطلاحًا؟"},{"id":"u21_2","label":"قطعية الثبوت وظنيته","segs":[["matn","وأقسام الأدلة باعتبار قطعيتها وظنيتها: ١. قطعية الثُّبوت: وهي الأدلَّة التي وصلتنا من طريق يقطع بصحّته من غير زيادة ولا نقصان، ولا يكون ذلك إلا في المتواتر ٣. ظنيّة الثُّبوت: وهي الأدلة التي من طريق لا يقطع بصحته؛ لاحتمال كذب الرَّاوي، أو عدم ضبطه، أو غير ذلك: كسُنَّة الآحاد."]],"q":"ما قطعية الثبوت وظنية الثبوت في الأدلة مع التمثيل؟"},{"id":"u21_3","label":"قطعية الدلالة وظنيتها","segs":[["matn","٢. قطعية الدَّلالة: وهي الأدلة على المطلوب بما لا يقبل الاحتمال بوجه ما: أي لا يحتمل إلا معنى واحداً ٤. ظنيّة الدَّلالة: وهي الأدلّة على المطلوب بما يقبل الاحتمال بوجه ما: أي يحتمل أكثر من معنى واحد"]],"q":"ما قطعية الدلالة وظنية الدلالة في الأدلة؟"},{"id":"u21_4","label":"ما تثبته الأدلة من أحكام","segs":[["matn","والأحكام التي تفيدها هذه الأدلَّة السَّميعة باعتبار ظنيتها وقطعيتها هي: ١. قطعي الثُّبوت والدَّلالة يثبت به الافتراض والتَّحريم. ٢. قطعي الثُّبوت وظني الدَّلالة أو ظني الثُّبوت وقطعي الدَّلالة يثبت به الإيجاب وكراهة التَّحريم. ٣. ظني الثُّبوت وظني الدَّلالة يثبت به السُّنية والاستحباب."]],"q":"ما الأحكام التي تثبتها الأدلة السمعية باعتبار قطعيتها وظنيتها؟"}],"sup":"المبحث التَّمهدي"},{"id":"u22","title":"ثانياً: تعريف القرآن الكريم","group":"الباب الثَّاني الكتاب","units":[{"id":"u22_1","label":"أشهر أسماء القرآن","segs":[["matn","القرآن: أشهر أسمائه في اللغة وهي: القرآن، والكتاب، والذِّكر، والفرقان، والمصحف"]],"q":"ما أشهر أسماء القرآن؟"},{"id":"u22_2","label":"القرآن لغةً","segs":[["matn","القرآن: مصدر قرأ، فقرأت الكتاب قراءةً وقُرآناً، ومنه سُمِّيَ القرآن"]],"q":"ما معنى القرآن لغةً؟"},{"id":"u22_3","label":"القرآن اصطلاحًا","segs":[["matn","القرآن: المُنزل على رسول الله ﷺ، المكتوب في المصاحف، المنقول عن النَّبيّ ﷺ، نقلاً متواتراً بلا شُبهة"]],"q":"ما تعريف القرآن اصطلاحًا؟"}],"sup":"المبحث التَّمهدي"},{"id":"u23","title":"ثالثاً: الفرق بين القرآن والحديث القدسي","group":"الباب الثَّاني الكتاب","units":[{"id":"u23_1","label":"فروق القرآن والقدسي: النزول والنقل","segs":[["matn","وَيُفَرَّق بين القرآن والحديث القدسي بما يلي ١. إنَّ القرآن نزل به جبريل عليه السلام إلى النَّبي ﷺ لفظاً ومعنى، أما الحديث القدسي فقد نزل روح القدس ـ وهو جبريل عليه السلام ـ إلى النَّبي ﷺ بمعناه؛ ٢. إنَّه نُقل القرآن تواتراً، وأما الحديث القدسي فليس متواتر."]],"q":"ما الفرق بين القرآن والحديث القدسي في النزول والنقل؟"},{"id":"u23_2","label":"فروق أخرى بين القرآن والقدسي","segs":[["matn","إنَّه تصحّ الصَّلاة بالقرآن، ولا تصح بالحديث القدسي. إنَّ القرآن مُعجز، بخلاف الحديث القدسي. إنَّ القرآن يتعبّد بتلاوته، ولا يتعبّد بألفاظ الحديث القدسي. إنَّ جاحد القرآن كافر، بخلاف جحود القدسي."]],"q":"ما الفروق الأخرى بين القرآن والحديث القدسي؟"}],"sup":"المبحث التَّمهدي"},{"id":"u24","title":"رابعاً: إنَّ القرآن هو النَّظم والمعنى جميعاً","group":"الباب الثَّاني الكتاب","units":[{"id":"u24_1","label":"معنى النظم والمعنى","segs":[["matn","القرآن هو النَّظم والمعنى: أراد بالنَّظم: العبارات، وبالمعنى: مدلولات العبارات"]],"q":"ما المراد بالنظم والمعنى في تعريف القرآن؟"},{"id":"u24_2","label":"القراءة بالفارسية في الصلاة","segs":[["matn","صحَّ رجوع الإمام أبي حنيفة رضي الله عنه عن جواز القراءة بالفارسية مع القدرة على العربية، وعليه الفتوى."]],"q":"ما حكم القراءة بالفارسية في الصلاة مع القدرة على العربية؟"}],"sup":"المبحث التَّمهدي"},{"id":"u25","title":"خامساً: هل البسملة آية من القرآن؟","group":"الباب الثَّاني الكتاب","units":[{"id":"u25_1","label":"البسملة آية فذة","segs":[["matn","البسملة: الصَّحيح أنَّها آية فذَّة من القرآن، ليست من الفاتحة، ولا من سورة أخرى، أُنزلت لبيان مبادئها وخواتيها؛ للفصل بينها، وهو مختار متأخري الحنفية"]],"q":"ما الصحيح في البسملة عند متأخري الحنفية؟ ولماذا أُنزلت؟"}],"sup":"المبحث التَّمهدي"},{"id":"u26","title":"سادساً: حكم الاحتجاج بالقراءة الشَّاذة في الأحكام","group":"الباب الثَّاني الكتاب","units":[{"id":"u26_1","label":"تعريف الشاذ والمتواتر","segs":[["matn","الشَّاذ لُغةً: المنفرد، وفي الاصطلاح: عكس المتواتر، والمتواتر قراءة ساعدها خطّ المصحف، مع صحّة النَّقل فيها، ومجيئها على الفصيح من لغة العرب"]],"q":"ما تعريف القراءة الشاذة والقراءة المتواترة؟"},{"id":"u26_2","label":"شرط العمل بالقراءة الشاذة","segs":[["matn","ويشترط الشُّهرة في القراءة الشَّاذة عند السَّلف للعمل بها؛ والزِّيادة عندنا تثبت بالخبر المشهور."]],"q":"ما شرط العمل بالقراءة الشاذة عند السلف؟"},{"id":"u26_3","label":"المعتبر حال الدليل وقت المجتهد","segs":[["matn","المعتبر حال الدَّليل في وقت المجتهد، لا حال من جاء بعده"]],"q":"هل المعتبر حال الدليل وقت المجتهد أم بعده؟"}],"sup":"المبحث التَّمهدي"},{"id":"u30","title":"المبحث الأول الخاصّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u30_1","label":"تعريف الخاص","segs":[["matn","الخاصّ: وهو ما وُضِع لمعنى واحد معلوم على الانفراد، جنساً: كإنسان، أَو نوعاً: كرجل، أَو عيناً: كزيد"]],"q":"ما تعريف الخاص مع التمثيل؟"},{"id":"u30_2","label":"حكم الخاص","segs":[["matn","وحكمُ الخاصّ: تناولُ المخصوص قطعاً بلا احتمال بيان: أي لا يحتمل البيان؛ لكونه بيِّناً في نفسه."]],"q":"ما حكم الخاص؟"}]},{"id":"u32","title":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب","group":"الباب الثَّاني الكتاب","units":[{"id":"u32_1","label":"الوجوب مختص بصيغة الأمر","segs":[["matn","الأمر: يختصُّ بصيغة لازمة فلا يكون الفعل موجباً؛ لأنَّ الوجوب بالأمر، والأمر مختصّ بصيغته، وهي افعل، فيستفاد الإيجاب منها."]],"q":"هل يختص الوجوب بصيغة الأمر أم يكون الفعل موجبًا؟ ولماذا؟"},{"id":"u32_2","label":"الأمر بعد الحظر","segs":[["matn","الأمرُ المطلق يفيد الوجوب بعد الحظر أو قبله"]],"q":"ماذا يفيد الأمر المطلق بعد الحظر؟"},{"id":"u32_3","label":"الأمر لا يقتضي التكرار","segs":[["matn","الأمرُ المطلق لا يقتضي تكرار المأمور به، وهو أن يفعلَه ثمّ يعود إليه، ولا يكون التِّكرار محتملاً من محتملات الأمر؛ وليس سبب تكرُّر العبادات هو أنَّ الأمر يقتضي التِّكرار، وإنَّما لتكرّر أسبابها عند الجمهور"]],"q":"هل يقتضي الأمر المطلق التكرار؟ وما سبب تكرر العبادات؟"},{"id":"u32_4","label":"وقوع الأمر على أقل الجنس","segs":[["matn","فيقع الأمر فيما للمأمور به أفراد على أَقلّ جنس المأمور، وهو الفرد الحقيقي: كالطَّلقة الواحدة، ويحتمل كلّ الجنس باعتبار معنى الفرديّة: كالطَّلاقات الثَّلاث، لا باعتبار معنى العدد"]],"q":"علامَ يقع الأمر فيما للمأمور به أفراد، وماذا يحتمل؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u33","title":"المطلب الثَّاني: حكم الأمر على صورتين","group":"الباب الثَّاني الكتاب","units":[{"id":"u33_1","label":"تعريف الأداء","segs":[["matn","أداءٌ: وهو إقامةُ الواجب: أي إخراجُه إلى الوجود على حسب الصُّورة التي وجبت بالأمر ابتداءً"]],"q":"ما تعريف الأداء؟"},{"id":"u33_2","label":"تعريف القضاء","segs":[["matn","قضاءٌ: وهو تسليم مثل الواجب بالسَّبب، وهو ما في الذمة، أو فِعْل المأمور به بعد وقته"]],"q":"ما تعريف القضاء؟"},{"id":"u33_3","label":"تعريف الإعادة","segs":[["matn","وأمَّا الإعادة فهي فِعلُ ما فُعِلَ أوّلاً مع نوع من الخلل ثانياً"]],"q":"ما تعريف الإعادة؟"},{"id":"u33_4","label":"سبب وجوب القضاء","segs":[["matn","يجب الأداءُ والقضاءُ بسببٍ واحدٍ، وهو الأمرُ الذي وَجَبَ به الأداء عند الجمهور؛ ولا يكون القضاء بسبب جديد كما قال العراقيون من الحنفية"]],"q":"بمَ يجب القضاء عند الجمهور؟ وما قول العراقيين من الحنفية؟"},{"id":"u33_5","label":"أنواع الأداء","segs":[["matn","أَنواع الأداء ثلاثةٌ: أـ أداء كامل: وهو ما يُؤَدَّى كما شُرِع ب ـ أداء قاصر: وهو النَّاقص عن صفته ج ـ أداء شبيه بالقضاء: كفعل اللاحق"]],"q":"ما أنواع الأداء الثلاثة؟"},{"id":"u33_6","label":"أنواع القضاء","segs":[["matn","أنواع القضاء ثلاثة: أ. قضاء بمثل معقول: كالصَّلاة للصَّلاة والصَّوم للصَّوم، ب. قضاء بمثل غير معقول: أي يقصر العقل عن إدراك المماثلة فيه؛ جـ. قضاءٌ بمعنى الأداء: كتكبير مَن أدرك الإمام في العيد راكعاً في الرُّكوع"]],"q":"ما أنواع القضاء الثلاثة مع التمثيل؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u34","title":"المطلب الثَّالث: حسن الأمر","group":"الباب الثَّاني الكتاب","units":[{"id":"u34_1","label":"الحسن لازم للمأمور به","segs":[["matn","فالحسنُ لازمٌ للمأمور به؛ لأنَّ الآمر حكيم، فلا يأمر بشيء إلا لحسنه، والعقل آلة يدرك بها حسن بعض الأشياء وقُبحها"]],"q":"هل الحسن لازم للمأمور به؟ ولماذا؟ وما دور العقل؟"},{"id":"u34_2","label":"الحسن لمعنى في عينه","segs":[["matn","والحُسن على قسمين: الأول: حسن لمعنى حاصل في عين الأمر، وهذا الحسن بالنَّظر إلى حكم الأمر نوعان: ١. حسن لمعنى في وصف الأمر، ٢. حسن لمعنى في عين الأمر مشابهٌ للحسن لمعنى في غير الأمر: كالزَّكاة"]],"q":"ما نوعا الحسن لمعنى في عين المأمور به؟"},{"id":"u34_3","label":"حكم الحسن لعينه","segs":[["matn","وحكم ما وجب في عين الأمر بِصُوره: أنَّه لا يسقط إلا بالأداء أو باعتراض ما يُسقطه كالحيض في الصَّلاة"]],"q":"ما حكم ما حسن لمعنى في عينه؟"},{"id":"u34_4","label":"الحسن لمعنى في غيره","segs":[["matn","الثّاني: حسن لمعنى في غير المأمور به، وذلك المعنى الخارج الذي حسن المأمور به لأجله على نوعين: ١. أن لا يؤدَّى المعنى الخارج: كالصَّلاة بالمأمور به كالوضوء، ٢. أن يؤدَّى المعنى الخارج الذي حسن المأمور به لأجله به: كإعلاء كلمة الله بالمأمور به وهو الجهاد،"]],"q":"ما نوعا الحسن لمعنى في غير المأمور به مع التمثيل؟"},{"id":"u34_5","label":"حكم الحسن لغيره","segs":[["matn","وحكم ما حسن لغيره بِصُوره: هو بقاءُ الوجوب ببقاء غيره الذي حسن لأجله، وسقوطه بسقوطه"]],"q":"ما حكم ما حسن لمعنى في غيره؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u35","title":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت","group":"الباب الثَّاني الكتاب","units":[{"id":"u35_1","label":"الأمر المطلق عن الوقت","segs":[["matn","الأول: مطلق عن الوقت؛ بأن لا يُذكر له وقتٌ محدودٌ على وجهٍ يفوت الأداء بفواته، بحيث لا يكون المأمورُ به محدداً بوقتٍ: كالأمر بالزَّكاةِ وصدقةِ الفطر، فلا يجب الأداءُ على الفور"]],"q":"ما الأمر المطلق عن الوقت، وهل يجب أداؤه على الفور؟"},{"id":"u35_2","label":"الأمر المقيد بالوقت","segs":[["matn","الثاني: مقيّدٌ بالوقت؛ بحيث يفوت الأداء بفوات الوقت؛ لاختصاصه بوقت محدّد، وهو أَربعة أَقسام"]],"q":"ما الأمر المقيد بالوقت، وكم قسمًا هو؟"},{"id":"u35_3","label":"الوقت ظرف وشرط وسبب","segs":[["matn","١. أن يكون الوقت ظرفاً وشرطاً وسبباً، وتتحقَّق هذه المعاني الثَّلاثة: ظرفاً وشرطاً وسبباً في وقت الصَّلاة. الظَّرف ما يفضل عن أداء الواجب بحيث لا يستوعب الواجب كلّ الوقت، الشَّرطَ ما يفوت أداء الواجب بفوته، السَّببَ ما يختلف أداء الواجب باختلاف صفته"]],"q":"ما معنى كون الوقت ظرفًا وشرطًا وسببًا، وأين يتحقق؟"},{"id":"u35_4","label":"نية التعيين في الصلاة","segs":[["matn","ومن أحكام الصَّلاة بسبب وجود هذه المعاني الثَّلاثة فيها: اشتراط نيّة تعيين فرض الوقت؛ ولا تسقط نيّة تعيين الصَّلاة إذا ضاق الوقت؛"]],"q":"ما حكم نية تعيين فرض الوقت، وهل تسقط بضيقه؟"},{"id":"u35_5","label":"الوقت معيار وشرط وسبب","segs":[["matn","٢. أن يكون الوقت معياراً وشرطاً وسبباً، وتتحقَّق هذه المعاني الثَّلاثة: معياراً وشرطاً وسبباً في وقت شهر رمضان."]],"q":"أين يكون الوقت معيارًا وشرطًا وسببًا؟"},{"id":"u35_6","label":"تأدي صوم رمضان بأي نية","segs":[["matn","فيتأدّى صيام رمضان بمطلق الاسم، وهو الصَّوم، ويتأدّى مع الخطأ في وصف الصَّوم، بأن ينوي صوم القضاء أو النَّذر أو النَّفل؛ إلا في المسافر ينوي واجباً آخر"]],"q":"بأي نية يتأدى صيام رمضان؟ وما المستثنى من ذلك؟"},{"id":"u35_7","label":"الوقت معيار فقط","segs":[["matn","٣. أن يكون الوقت معياراً فقط؛ بأن يكون صيام قضاء رمضان مُقَدَّراً؛ اشتراط تعيين أنَّه قضاء لرمضان؛ واشتراط أن يكون نيّة صيام القضاء من الليل"]],"q":"متى يكون الوقت معيارًا فقط، وما أحكامه؟"},{"id":"u35_8","label":"الوقت المشكل: الحج","segs":[["matn","٤. أن يكون الوقت مشكلاً يشبه المعيار ويشبه الظَّرفَ، فإنَّ الحجَّ يشبه وقته المعيار من حيث إنَّه لا يصحّ منه في عامّ واحد إلا حجّة واحدة، فيكون وجوب الحج على الفور لا على التَّراخي."]],"q":"متى يكون الوقت مشكلًا، وما أثر ذلك في الحج؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u36","title":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة","group":"الباب الثَّاني الكتاب","units":[{"id":"u36_1","label":"ما خوطب به الكفار","segs":[["matn","فالكفَّارُ مخاطبون بالإيمان بإجماع الفقهاء، ومخاطبون بالمشروع من العقوبات فيما اعتقدوا حرمته، ومخطابون بالمعاملات: كالبيع؛ لوجود التزامهم."]],"q":"بمَ خوطب الكفار من التكاليف؟"},{"id":"u36_2","label":"لا قضاء على الكافر إذا أسلم","segs":[["matn","والكافرُ إذا أسلم لا شيء عليه من قضاء ما مضى من العبادات في حالة الكُفر."]],"q":"هل على الكافر إذا أسلم قضاء ما مضى من العبادات؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u37","title":"النَّوع الثَّاني: النَّهي","group":"الباب الثَّاني الكتاب","units":[{"id":"u37_1","label":"تعريف النهي","segs":[["matn","النَّهي: وهو قول القائل لغيره على سبيل الاستعلاء: لا تفعل."]],"q":"ما تعريف النهي؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u38","title":"المطلب الأوّل: القبح للنَّهي","group":"الباب الثَّاني الكتاب","units":[{"id":"u38_1","label":"النهي يقتضي القبح","segs":[["matn","ويقتضي النَّهي صفة القُبح للمنهي عنه كالأمر في اقتضائه لصفة الحُسن للمأمور به؛"]],"q":"ماذا يقتضي النهي في المنهي عنه؟"},{"id":"u38_2","label":"القبيح لعينه وصورتاه","segs":[["matn","وينقسم القُبح للنَّهي إلى نوعين: ١. القبيح لمعنى في عين المنهي عنه، وهو على صورتين: أ. وضعاً: أي وضع للقبيح العقلي بقطع النَّظر عن ورود الشَّرع: كالكفر ب. شرعاً: أي إنَّ الشَّرع ورد بهذا القبح، وإلا فالعقل يُجوِّزه: كبيع الحرّ"]],"q":"ما صورتا القبيح لمعنى في عين المنهي عنه مع التمثيل؟"},{"id":"u38_3","label":"ما يندرج تحت القبيح لعينه وحكمه","segs":[["matn","القَبيح لعينه: النَّهي عن الأفعال الحسية، وهي التي تُعرف بالحسّ، ولا يتوقّف وجودها على الشَّرع وحكم ما قَبح لعينه: أنَّ المنهيَ عنه غيرُ مشروع أصلاً."]],"q":"ما الذي يندرج تحت القبيح لعينه، وما حكمه؟"},{"id":"u38_4","label":"القبيح لغيره وصورتاه","segs":[["matn","٢. القبيح لمعنى في غير المنهي عنه على صورتين: أـ وصفاً، وهو ما يكون القبيحُ قائماً بالمنهي عنه لا يقبل الانفكاك: كوصف صيام يوم النَّحر، ب ـ مجاوراً: وهو ما يكون القبيح مصاحباً ومقارناً في الجملة؛ بأن يوجد في بعض الأحيان وينفك في أحيان أخرى: كالبيع وقت النِّداء،"]],"q":"ما صورتا القبيح لمعنى في غير المنهي عنه مع التمثيل؟"},{"id":"u38_5","label":"النهي عن الأمور الشرعية","segs":[["matn","ويندرج تحت القبيح لغيره بصورتيه: النَّهي عن الأمور الشَّرعية، وهي التي يتوقَّف تحقيقها على الشَّرع: كالصَّلاة والصَّوم والبيع والإجارة، وهذا معنى أنَّ النَّهي في الأفعال الشَّرعيَّة يدلُّ على جواز أصلها، والمنع في وصف خاصّ لها"]],"q":"ما الذي يندرج تحت القبيح لغيره، وعلامَ يدل النهي فيه؟"},{"id":"u38_6","label":"حكم القبيح لغيره","segs":[["matn","وحكم القبيح لغيره: أنَّه مشروعٌ بأَصلِهِ غيرَ مشروع بوصفِه، ففي العباداتِ يصحُّ التزامها، كما في نذر صيام يوم النَّحر، وفي المعاملاتِ تفيد الملك عند اتصال القبض"]],"q":"ما حكم القبيح لغيره في العبادات والمعاملات؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u39","title":"المطلب الثَّاني: الأمر والنَّهي في حقّ الضدّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u39_1","label":"الأمر والنهي في حق الضد","segs":[["matn","الأمرُ بالشَّيء يقتضي كراهة ضدِّه، والنَّهي عن الشَّيء يقتضي أن يكون ضدُّه في معنى سُنّة مؤكّدة"]],"q":"ماذا يقتضي الأمر بالشيء والنهي عنه في حق ضده؟"}],"sup":"المبحث الأول الخاصّ"},{"id":"u40","title":"المبحث الثَّاني العام","group":"الباب الثَّاني الكتاب","units":[{"id":"u40_1","label":"تعريف العام","segs":[["matn","العام: وهو ما تناول أفراداً متفقة الحدود على سبيل الشُّمول بخلاف اسم الجنس نحو: رجل، فإنَّه يتناول أَفراداً متفقةَ الحدود لكن على سبيل البدل"]],"q":"ما تعريف العام، وبمَ يفارق اسم الجنس؟"},{"id":"u40_2","label":"حكم العام","segs":[["matn","وحكم العام: إيجابُ الحكم فيما يتناوله قطعاً فيجوز نسخُ الخاصّ بالعامّ، وهذا حكم العام قبل التَّخصيص، فأمّا بعده فيكون ظنيّاً"]],"q":"ما حكم العام قبل التخصيص وبعده؟"},{"id":"u40_3","label":"قسما ألفاظ العموم","segs":[["matn","وألفاظ العموم قسمان: ١. عام بصيغته ومعناه: فهو صيغة كلُّ جمع مثل: الرِّجال والنِّساء ٢. عام بمعناه دون صيغته،"]],"q":"ما قسما ألفاظ العموم؟"},{"id":"u40_4","label":"من صيغ العام بالمعنى (١)","segs":[["matn","العام بالمعنى: أ. ما هو فرد وضع للجمع، مثل: الرَّهط والقوم والطَّائفة والجماعة، ب. كلمة: «كل»، وهي للإحاطة على سبيل الإفراد ج. كلمة: «الجميع»، وهي عامّة مثل «كلّ»، إلا أنَّها تُوجب الاجتماع دون الانفراد،"]],"q":"ما دلالة الفرد الموضوع للجمع وكلمتي «كل» و«الجميع» على العموم؟"},{"id":"u40_5","label":"من صيغ العام بالمعنى (٢)","segs":[["matn","د. أسماء الشَّرط: كمن وما وأي: هـ. أسماء الاستفهام: كمن ومتى وأين: و. كلمة: «الذي»، وهي عامة فيما يعقل وفيما لا يعقل."]],"q":"ما دلالة أسماء الشرط والاستفهام وكلمة «الذي» على العموم؟"},{"id":"u40_6","label":"من صيغ العام بالمعنى (٣)","segs":[["matn","س. النَّكرةُ إذا اتصل بها دليل العموم؛ فالنَّكرة في النَّفي تعمّ، وفي الإثبات تخصّ؛ ح. أسماء الأجناس المُعَرَّفة بتعريف اللام الاستغراقية أو بتعريف الإضافة للاستغراق، ط. النَّكرة إذا اتصل بها وصف عام، ي. الجمع المُعرَّف بغير اللام"]],"q":"متى تعمّ النكرة، وما دلالة أسماء الأجناس المعرّفة والجمع المعرّف؟"}]},{"id":"u41","title":"المبحثُ الثَّالث المشترك","group":"الباب الثَّاني الكتاب","units":[{"id":"u41_1","label":"تعريف المشترك","segs":[["matn","المشترك: وهو ما تناول أَفراداً مختلفة الحدود بالبدل: أي هذا أو هذا، أو هو لفظ وضع وَضْعاً شخصياً لمعنين فأكثر بأوضاع متعددة ابتداءً"]],"q":"ما تعريف المشترك؟"},{"id":"u41_2","label":"حكم المشترك","segs":[["matn","وحكمُ المشترك: التَّوقف فيه من غير اعتقاد حكم معلوم سوى أنَّ الثابت به حقّ حتى يقوم مُرَجِّح للمعنى المراد،"]],"q":"ما حكم المشترك؟"},{"id":"u41_3","label":"لا عموم للمشترك","segs":[["matn","ولا عموم للمشترك عندنا، فلا يستعمل في أكثر من معنى واحد؛"]],"q":"هل للمشترك عموم فيستعمل في أكثر من معنى؟"}]},{"id":"u42","title":"المبحث الرَّابع المؤوّل","group":"الباب الثَّاني الكتاب","units":[{"id":"u42_1","label":"تعريف المؤول","segs":[["matn","المؤوّل: وهو ما ترجَّح من المشترك بعض وجوهِهِ بغالبِ الرَّأي. والتَّأويل ليس خاصاً بترجيح أحد معاني المشترك، بل يشمل كلَّ لفظ ترجّح بعض محتملاته بدليل فيه شبهة؛"]],"q":"ما تعريف المؤول؟ وهل يختص التأويل بالمشترك؟"},{"id":"u42_2","label":"حكم المؤول","segs":[["matn","وحكم المؤول: وجوبُ العمل به؛ لأنَّه دليلٌ ظنيّ على احتمال الغلط؛"]],"q":"ما حكم المؤول؟ ولماذا؟"}]},{"id":"u45","title":"أولاً: مراتب الظُّهور أربعة","group":"الباب الثَّاني الكتاب","units":[{"id":"u45_1","label":"الظاهر وحكمه","segs":[["matn","الأوّل: الظَّاهر: وهو كلام وضح المعنى الوضعي بنفس صيغته من غير نظر إلى أمر آخر، ويكون محتملاً للتأويل إن كان خاصاً والتَّخصيص إن كان عاماً، وحكمُ الظَّاهر: وجوبُ العمل بما ظَهَر منه على سبيل القطع"]],"q":"ما تعريف الظاهر، وما حكمه؟"},{"id":"u45_2","label":"النص وحكمه","segs":[["matn","الثَّاني: النَّصُّ: وهو ما زاد المرادُ به وضوحاً على الظَّاهر بمعنى من المتكلِّم، وهو سوقُ الكلام له وحكم النَّص: وجوب العمل بما اتضح قطعاً على احتمال تأويل"]],"q":"ما تعريف النص، وما حكمه؟"},{"id":"u45_3","label":"المفسر وحكمه","segs":[["matn","الثَّالث: المُفَسَّر: وهو ما ازداد وضوحاً على النَّصِّ من غير احتمال تأويل إن كان خاصّاً، أو تخصيص إن كان عامّاً. وحكمُ المُفَسَّر: وجوبُ العمل به على احتمال النَّسخ"]],"q":"ما تعريف المفسَّر، وما حكمه؟"},{"id":"u45_4","label":"المحكم وحكمه","segs":[["matn","الرَّابع: المُحكم: وهو ما أُحكم المرادُ به عن احتمال النَّسخ. وحكم المُحكم: وجوب العمل من غير احتمال للتَّأويل ولا للنَّسخ."]],"q":"ما تعريف المحكم، وما حكمه؟"}],"sup":"الوجه الأول: الظُّهور"},{"id":"u46","title":"ثانياً: التَّرجيح بين مراتب الظُّهور","group":"الباب الثَّاني الكتاب","units":[{"id":"u46_1","label":"الترجيح بين مراتب الظهور","segs":[["matn","يظهر التَّفاوت بين هذه الأربعة عند التَّعارض؛ لأنَّه لا تفاوت بينها في إيجاب الحُكم قطعاً، فيصير الظَّاهر متروكاً عند معارضة النَّصّ، والظَّاهر والنَّصّ عند معارضة المُفسَّر، والمُفسَّر عند معارضة المُحكم"]],"q":"متى يظهر التفاوت بين الظاهر والنص والمفسر والمحكم، وأيها يُترك؟"}],"sup":"الوجه الأول: الظُّهور"},{"id":"u47","title":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع","group":"الباب الثَّاني الكتاب","units":[{"id":"u47_1","label":"الخفي وحكمه","segs":[["matn","الأول: الخفي: هو اسم لكلام استتر معناه بسبب عارض نشأ من غير الصِّيغة، وحكم الخفي: النَّظر فيما خَفي فيه لإظهار هل خفاؤه لزيادة فيه فيأخذ حكم الأصل، أو خفاؤه لنقصان فيه فلا يأخذ حكم الأصل."]],"q":"ما تعريف الخفي، وما حكمه؟"},{"id":"u47_2","label":"المشكل وحكمه","segs":[["matn","الثَّاني: المشكل: وهو اسم لكلام يحتمل المعاني المتعددة، ويكون المراد واحداً منها، وحكم المشكل: اعتقاد حَقيّةِ المرادِ إلى أن يتبيّن بالطَّلب والتَّأمّل،"]],"q":"ما تعريف المشكل، وما حكمه؟"},{"id":"u47_3","label":"المجمل وحكمه","segs":[["matn","الثَّالث: المُجْمَل: ما خفي المراد منه خفاء لا يدركُ إلا ببيان من المُجْمِل، وحكمُ المُجْمَل: التَّوقُّفُ فيه إلى أن يَتَبيَّنَ مُرادُه من المُجْمِل"]],"q":"ما تعريف المجمل، وما حكمه؟"},{"id":"u47_4","label":"المتشابه وحكمه","segs":[["matn","الرَّابع: المتشابه: وهو اسم لما انقطع رجاء معرفة المراد منه للأُمَّة في الدُّنيا، وحكم المتشابه: التَّوقُّف فيه أبداً بعدم جواز العمل به مع اعتقاد حَقيَّة المراد به"]],"q":"ما تعريف المتشابه، وما حكمه؟"}]},{"id":"u48","title":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة","group":"الباب الثَّاني الكتاب","units":[{"id":"u48_1","label":"تعريف الحقيقة","segs":[["matn","الأَوَّل: الحقيقة: وهي اسم للفظ أُريد به معنى وُضِع له ذلك اللَّفظ."]],"q":"ما تعريف الحقيقة؟"},{"id":"u48_2","label":"تعريف المجاز","segs":[["matn","الثَّاني: المجازُ: وهو اسم للفظ أُريد به غير ما وُضِع له لعلاقةٍ بينهما"]],"q":"ما تعريف المجاز؟"},{"id":"u48_3","label":"من أحكام الحقيقة والمجاز","segs":[["matn","ومن أحكام الحقيقة والمجاز: ١. استحالةُ اجتماع الحقيقة والمجاز مرادين بلفظٍ واحدٍ في وقتٍ واحدٍ؛ ٢. متى أَمكن العمل بالحقيقةِ سَقَطَ المجاز؛"]],"q":"ما الحكمان المذكوران أولًا من أحكام الحقيقة والمجاز؟"},{"id":"u48_4","label":"ترك الحقيقة: المتعذرة والمهجورة","segs":[["matn","٣. الحالات التي تُترك فيه الحقيقة إلى المجاز كثيرة، ومنها: أ. إن كانت الحقيقةُ متعذِّرةً ـ وهي ما لا يُصاب به إلا بمشقّة ـ تحوَّل القولُ إلى المجاز، ب. إن كانت الحقيقة مهجورةً: وهي ما يُمكن الوصولُ إليها إلاّ أنَّ النَّاسَ هجروها والمهجورُ شرعاً كالمهجور عادة"]],"q":"متى تُترك الحقيقة المتعذرة والمهجورة إلى المجاز؟"},{"id":"u48_5","label":"ترك الحقيقة بالدلالات","segs":[["matn","ج. إن كان الكلام على حقيقته لا يستقيم إلا بتقدير محذوف، ويُسمّى بـ: «دلالةٍ في محلِّ الكلام» د. إن كان حال المتكلّم يصرف الكلام عن حقيقته، ويُسمَّى بـ: «دلالة معنى يرجع إلى المتكلِّم» هـ. إن كان سياق الكلام يصرفه عن الحقيقية، ويُسمَّى بـ: «دلالةِ سياق النَّظم»، و. إن كان تركيب اللفظ لغةً يصرفه عن حقيقته، ويُسمّى بـ: «دلالةِ اللفظ في نفسِه»"]],"q":"ما الدلالات الأربع التي تُترك بها الحقيقة إلى المجاز؟"},{"id":"u48_6","label":"الصريح وحكمه","segs":[["matn","الثَّالث: الصَّريح: وهو لفظ ظَهَرَ المرادُ منه ظُهوراً تامّاً بكثرةِ الاستعمال، وحكم الصَّريح: ثبوت ما يوجبه اللفظ الصَّريح حال كونه مستغنياً عن العزيمة: أي النِّيَّة،"]],"q":"ما تعريف الصريح، وما حكمه؟"},{"id":"u48_7","label":"الكناية وحكمها","segs":[["matn","الرَّابعُ: الكنايةُ: وهو ما استتر المراد منه واحتمل أكثر من معنى، أو هو لفظ لم يظهر المراد به إلاّ بقرينة وحكم الكناية: عدمُ العمل بالكناية بدون نيّة؛"]],"q":"ما تعريف الكناية، وما حكمها؟"},{"id":"u48_8","label":"الأصل الصريح وأثر الفرق","segs":[["matn","والأصلُ في الكلام هو الصَّريح؛ ويظهر هذا التَّفاوت الحاصل بين الصَّريح والكناية فيما يُدرأ بالشُّبهات، حيث جاز إثباتها بالصَّريح دون الكناية،"]],"q":"ما الأصل في الكلام، وأين يظهر الفرق بين الصريح والكناية؟"}]},{"id":"u49","title":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى)","group":"الباب الثَّاني الكتاب","units":[{"id":"u49_1","label":"حصر وجوه الاستدلال","segs":[["matn","وجوه الاستدلال: وهي أربعة أقسام؛ لأنَّه إمّا أن يدلَّ على الحكم بعبارته، أو إشارته، أو دلالته، أو اقتضائه؛ فإن كان اللفظ مسوقاً فهو العبارة، وإلا فهو الإشارة. وإن كان الحكم مفهوماً منه لغةً فهي الدَّلالة، أو شرعاً فهو الاقتضاء،"]],"q":"ما وجوه الاستدلال، وما وجه حصرها في أربعة؟"},{"id":"u49_2","label":"عبارة النص","segs":[["matn","الأول: الاستدلال بعبارة النَّصِّ: وهو اللفظ الدَّالّ على معنى سيق اللفظ له بلا تأمّل، أو هو العمل بظاهر ما سيق الكلام له."]],"q":"ما الاستدلال بعبارة النص؟"},{"id":"u49_3","label":"إشارة النص","segs":[["matn","الثَّاني: الاستدلالُ بإشارةِ النَّصِّ: وهو العملُ بحكم ثبت بنظمه أو دلالة اللفظ على حكم لا يظهر ظهوراً أَولياً، ولا يكون مقصوداً ولا مسوقاً لأجله الكلام،"]],"q":"ما الاستدلال بإشارة النص؟"},{"id":"u49_4","label":"حكم العبارة والإشارة","segs":[["matn","والعبارةُ والإشارةُ سواء في إيجاب الحكم؛ لأنَّ كلاً منهما يُفيدُ الحكم بظاهره، ولكنَّ العبارةُ أرجح عند التَّعارض من الإشارة؛ وللإشارة عموم كالعبارة؛"]],"q":"ما حكم العبارة والإشارة، وأيهما أرجح عند التعارض؟"},{"id":"u49_5","label":"دلالة النص","segs":[["matn","الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ: هو حكمٌ ثبت بسبب معنى النَّصِّ لغةً لا بعين النَّصِّ، فالنَّهي عن التَّأفيف يُعلم به حرمة الضَّرب من غير اجتهاد،"]],"q":"ما الاستدلال بدلالة النص مع التمثيل؟"},{"id":"u49_6","label":"حكم الثابت بالدلالة","segs":[["matn","والثَّابتُ بدلالةِ النَّصِّ كالثَّابت بعبارته وإشارته من حيث إنَّ كلاً منهما يوجب الحكم قطعاً؛ لكن عند التَّعارض، فإنَّ الإشارةَ تُقَدَّمُ على الدَّلالة، والثَّابتُ بدلالة النَّصِّ لا يحتمل التَّخصيص؛ إذ لا عموم للدَّلالة؛"]],"q":"ما حكم الثابت بدلالة النص، وما مرتبته عند التعارض؟"},{"id":"u49_7","label":"اقتضاء النص","segs":[["matn","الرَّابع: الثَّابتُ باقتضاء النَّصِّ: وهو حكمٌ لم يَعمل النَّصِّ إلاّ بشرط تقدُّمه على النَّصِّ، فيكون المقصود باقتضاء النَّصِّ: هو تقدير محذوف حتى يستقيم الكلام صدقاً أو شرعاً أو عقلاً،"]],"q":"ما الثابت باقتضاء النص؟"},{"id":"u49_8","label":"حكم الثابت بالاقتضاء","segs":[["matn","والثَّابتُ بالاقتضاء كالثّابت بدلالة النَّصِّ في إفادته وجوب الحكم قطعاً، ولكن عند تعارض الاقتضاء مع الدَّلالة ترجَّح الدَّلالة على الاقتضاء. والثَّابتُ بالاقتضاء لا يحتمل التَّخصيص؛ إذ لا عموم له؛"]],"q":"ما حكم الثابت بالاقتضاء، وما مرتبته عند التعارض؟"}]},{"id":"u50","title":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية","group":"الباب الثَّاني الكتاب","units":[{"id":"u50_1","label":"ما عدا الوجوه الأربعة فاسد","segs":[["matn","وما عدا هذه الوجوه الأربعة في الاستدلال على الأحكام، فهي فاسدةٌ عند الحنفيّة؛"]],"q":"ما حكم ما عدا الوجوه الأربعة في الاستدلال عند الحنفية؟"}]},{"id":"u51","title":"المطلب الأول: الاحتجاج بمفهوم المخالفة","group":"الباب الثَّاني الكتاب","units":[{"id":"u51_1","label":"التنصيص لا يدل على التخصيص","segs":[["matn","فالتَّنصيصُ على الشَّيء باسم يدلّ على الذَّات دون الصِّفة، سواءٌ كان علماً أو اسم جنس، لا يدلُّ على تخصيص الحكم بذلك الشَّيء؛"]],"q":"هل يدل التنصيص على الشيء باسمه على تخصيص الحكم به؟"},{"id":"u51_2","label":"المنطوق والمفهوم","segs":[["matn","المنطوق: هو ما يدلّ عليه لفظ من ألفاظ العبارة، ويشمل عبارة النَّصِّ وإشارة النَّصِّ عند الحنفية. والمفهوم: هو ما دلَّ عليه مباشرة غير اللفظ المذكور في تلك العبارة، وهو قسمان:"]],"q":"ما تعريف المنطوق والمفهوم؟"},{"id":"u51_3","label":"مفهوم الموافقة","segs":[["matn","١. مفهوم الموافقة: وهو دلالةُ العبارة على ثبوت حكم المنطوق للمسكوت بمجرد فهم اللغة: ويسمّى عند الحنفية «دلالة النَّصِّ». وهو معتبرٌ في نصوص القرآن والسُّنَّة وعبارات الفقهاء."]],"q":"ما مفهوم الموافقة، وما اسمه عند الحنفية، وهل هو معتبر؟"},{"id":"u51_4","label":"مفهوم المخالفة وأنواعه","segs":[["matn","٢. مفهوم المخالفة: وهو دلالة العبارة على ثبوت نقيض الحكم المنطوق للمسكوت: وهو أنواع: أ. مفهوم الصِّفة؛ ب. مفهوم الشَّرط؛ ج. مفهوم الغاية: د. مفهوم العدد؛ هـ. مفهوم اللَّقب؛"]],"q":"ما مفهوم المخالفة، وما أنواعه؟"},{"id":"u51_5","label":"مفهوم المخالفة عند الحنفية","segs":[["matn","مفهوم المخالفة: وعند الحنفية غير معتبر مطلقاً، بمعنى أنَّ النَّصِّ لا يدلّ على نقيض الحكم لغير المنطوق، فيبقى المفهوم مسكوتاً عنه، ومفهومُ المخالفة معتبرٌ في كتب الفقه عند الحنفيّة، وكذلك في مخاطبات النَّاس."]],"q":"ما حكم مفهوم المخالفة عند الحنفية؟"}],"sup":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية"},{"id":"u52","title":"المطلب الثاني: حمل المطلق على المُقَيَّد","group":"الباب الثَّاني الكتاب","units":[{"id":"u52_1","label":"تعريف المطلق والمقيد","segs":[["matn","المطلق: وهو ما دلَّ على بعض أفراد شائع لا قيد معه نحو: رقبة، والمُقَيَّدُ: وهو الدَّالُّ على مدلول المطلق بصفة زائدة،"]],"q":"ما تعريف المطلق والمقيد؟"},{"id":"u52_2","label":"الحمل في المحكوم به","segs":[["matn","أ. اتحاد الحادثة: فيُحمل المُطلق على المُقيَّد في المحكوم به في حادثةٍ واحدةٍ في هذه الحالة فقط؛ للضَّرورة في استحالة أنّ يكون لحادثة واحدة حكمان. ب. اختلاف الحادثة: فلا يُحمل المُطلق على المُقيَّد في المحكوم به في حادثتين."]],"q":"هل يُحمل المطلق على المقيد في المحكوم به عند اتحاد الحادثة واختلافها؟"},{"id":"u52_3","label":"لا حمل في سبب الحكم","segs":[["matn","أ. اتحاد الحادثة: فلا يُحمل فيها المُطلق على المُقيَّد في سبب الحكم في حادثة واحدة ب. اختلاف الحادثة: فلا يُحمل المُطلق على المُقيَّد في سبب الحكم في اختلاف الحادثة،"]],"q":"هل يُحمل المطلق على المقيد في سبب الحكم؟"},{"id":"u52_4","label":"علة عدم الحمل","segs":[["matn","وإنَّما لا يُحمل المُطلق على المُقيَّد في غير الصُّورة الأُولى التي سبقت؛ لإمكان العمل بالدَّليلين في المطلق على إطلاقه، وفي المقيَّد على تقييده، وكلُّ ما أَمكن إعمال الدَّليلين وَجَبَ بالعمل بهما، وهو أولى من إهمال أحدهما."]],"q":"لماذا لا يُحمل المطلق على المقيد في غير الصورة الأولى؟"}],"sup":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية"},{"id":"u53","title":"المطلب الثالث: القِران في النَّظم يُوجبُ القِران في الحكم","group":"الباب الثَّاني الكتاب","units":[{"id":"u53_1","label":"القران في النظم والحكم","segs":[["matn","فمعنى القِران في النَّظم: أي الجمع بين كلامين بحرفِ العطف، فإنَّه لا يوجب القِران في الحكم: أي لا يَلزم منه الاتفاق في الحكم بين المقترنين."]],"q":"ما معنى القران في النظم، وهل يوجب القران في الحكم؟"},{"id":"u53_2","label":"متى يوجب العطف الشركة","segs":[["matn","والعطف في الجملة على الجملة لا يوجب الشَّركة؛ لأنَّ الشَّركةَ إنَّما وجبت في الجملة النَّاقصة لافتقارها إلى ما تتمّ به فإذا تمَّت الجملة بنفسِها فلا تجب الشَّركة"]],"q":"هل يوجب عطف الجملة على الجملة الشركة؟ ولماذا؟"}],"sup":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية"},{"id":"u55","title":"المطلب الأول: حروف العطف","group":"الباب الثَّاني الكتاب","units":[{"id":"u55_1","label":"معنى الواو","segs":[["matn","الواو: فهي لِمطلق الجمع، فلا يستفاد منها أنَّ المقارنة في النَّظم توجب المقارنة في الحكم ـ كما سبق ـ، ولا تفيد التَّرتيب بين المعطوفات"]],"q":"ما معنى الواو في العطف؟"},{"id":"u55_2","label":"معنى الفاء","segs":[["matn","الفاء: فهي للتَّعقيب، فيتراخى المعطوف عن المعطوف عليه لزمان وإن لطف وتستعمل الفاء في أحكام العلل"]],"q":"ما معنى الفاء، وفيمَ تُستعمل؟"},{"id":"u55_3","label":"معنى ثم","segs":[["matn","ثُمَّ: وهي للتَّرتيب مع التَّراخي بمنزلة ما لو سكت ثُمَّ استأنف، وهذا هو الكامل في التَّراخي: أي في التَّكلّم والحكم جميعاً."]],"q":"ما معنى «ثم»؟"},{"id":"u55_4","label":"معنى بل","segs":[["matn","بل: وهي لإثبات ما بعد «بل» والإعراض عمّا قبل «بل» على سبيل تدارك الغلط"]],"q":"ما معنى «بل»؟"},{"id":"u55_5","label":"معنى لكن وشرطها","segs":[["matn","لكن: وهي للاستدراك بعد النَّفي وإن كان عطف مفرد على مفرد يشترط وقوعها بعد النَّفي، وإن كان عطف جملة على جملة يقع بعد النَّفي والإثبات."]],"q":"ما معنى «لكن»، وما شرط وقوعها؟"},{"id":"u55_6","label":"معنى أو","segs":[["matn","أو: وهو لأحد المذكورين وتُستعارُ «أو» للعموم فتصير بمعنى «واو» العطف لا عينها"]],"q":"ما معنى «أو»، ولماذا تُستعار؟"},{"id":"u55_7","label":"معاني حتى","segs":[["matn","حتى: وهي للغاية وتجيء للعطف وإن صلح الأوّل أن يكون سبباً للثَّاني تكون بمعنى «كي»"]],"q":"ما معاني «حتى»؟"}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u56","title":"المطلب الثَّاني: حروف الجرّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u56_1","label":"معنى الباء","segs":[["matn","الباء: وهي للإلصاق وتصحب الباء الأثمان"]],"q":"ما معنى الباء، وماذا تصحب؟"},{"id":"u56_2","label":"معاني على","segs":[["matn","على: وهي للاستعلاء، ويراد به الوجوب «الإلزام» وتستعمل للشَّرط ويستعار في المعاوضات المحضة بمعنى الباء"]],"q":"ما معاني «على»؟"},{"id":"u56_3","label":"معنى في","segs":[["matn","في: وهي للظَّرفيّة وتستعار للمقارنة إذا لم تصلح للظَّرفية"]],"q":"ما معنى «في»، ولماذا تُستعار؟"},{"id":"u56_4","label":"في الظاهرة والمضمرة","segs":[["matn","في: وتكون ظاهرةً مثل: صمتُ في هذا الشَّهر، وتكون مضمرةً مثل: صمتُ شهراً، والفرق بينهما: أنَّه في حالة الإضمار يقتضي الاستيعاب للكل، أما في حالة الإظهار فلا يقتضي الاستيعاب."]],"q":"ما الفرق بين «في» الظاهرة والمضمرة مع التمثيل؟"},{"id":"u56_5","label":"معاني من","segs":[["matn","من: وهي للتَّبعيض، هذا أصلُ وضعها، وباقي المعاني مجازٌ فيها وتكون للبيان وتكون زائدة"]],"q":"ما معاني «مِن»؟"},{"id":"u56_6","label":"معنى إلى","segs":[["matn","إلى: وهي لانتهاء الغاية، بالدَّلالة على أنَّ ما بعدها نهايةُ حكم ما قبلها"]],"q":"ما معنى «إلى»؟"}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u57","title":"المطلب الثَّالث: أسماء الظُّروف","group":"الباب الثَّاني الكتاب","units":[{"id":"u57_1","label":"معاني أسماء الظروف","segs":[["matn","«مع»: وهي للمقارنة، «قبل»: وهي للتَّقدُّم في الزَّمان على الزَّمان التي أُضيفت له، «بعد»: وهي للتَّأخر الزَّماني عن زمان ما أُضيفت إليه، «عند»: وهي للحضرة"]],"q":"ما معاني «مع» و«قبل» و«بعد» و«عند»؟"},{"id":"u57_2","label":"عند تفيد الوديعة","segs":[["matn","عند: فقوله: لفلان عندي ألف درهم، إقرارٌ بالوديعة لا بالدَّين"]],"q":"ما حكم قول القائل: لفلان عندي ألف درهم؟"}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u58","title":"المطلب الرَّابع: حروف الشَّرط","group":"الباب الثَّاني الكتاب","units":[{"id":"u58_1","label":"معنى إن","segs":[["matn","إن: وهي في الأصل للشَّرط؛ لاختصاصه بها، فتدخل في أمر على خطر الوجود"]],"q":"ما معنى «إن» في الأصل؟ ولماذا؟"},{"id":"u58_2","label":"معنى إذا بين المذهبين","segs":[["matn","إذا: وهي عند الكوفيين: للظَّرفِ وللشَّرطِ فإذا استعملت في الشَّرط لم يبق فيها معنى الوقت، وصارت بمعنى «إن»، وإليه ذهب أبو حنيفة. وعند البصريين: حقيقة في الظَّرف، وقد تجيء للشَّرط بلا سقوط معنى الظَّرف كـ«متى»، وإليه ذهب الصَّاحبان"]],"q":"ما معنى «إذا» عند الكوفيين والبصريين؟ ومن ذهب إلى كلٍّ؟"},{"id":"u58_3","label":"معنى كيف","segs":[["matn","كيف: وهي للسُّؤال عن الحال، وتُستعمل مجازاً بمعنى الحال إذا تعذَّر حملُها على الاستفهام"]],"q":"ما معنى «كيف»؟ ومتى تُستعمل مجازاً؟"}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u59","title":"الفصل الرَّابع البيان","group":"الباب الثَّاني الكتاب","units":[{"id":"u59_1","label":"بيان التقرير","segs":[["matn","البيان: وهو تأكيدُ الكلام بما يَقْطَعُ احتمال ما يلي: أ. المجاز ب. الخصوص ويصحُّ موصولاً ومفصولاً."]],"q":"ما بيان التقرير؟ وما الذي يقطع احتماله؟ وهل يصحُّ مفصولاً؟"},{"id":"u59_2","label":"بيان التفسير","segs":[["matn","البيان: وهو بيان ما فيه خفاء مما يلي: أ. المُجْمَل ب. المشترك وهذا القسم يصحُّ موصولاً ومفصولاً."]],"q":"ما بيان التفسير؟ وفيمَ يكون؟ وهل يصحُّ مفصولاً؟"},{"id":"u59_3","label":"بيان التغيير","segs":[["matn","البيان: وهو إخراج الكلام عما كان عليه بما يلي: أ. التَّعليقُ بالشَّرط ب. الاستثناء ويصحُّ موصولاً فقط"]],"q":"ما بيان التغيير؟ وبمَ يكون؟ وهل يصحُّ مفصولاً؟"},{"id":"u59_4","label":"حقيقة الاستثناء ومرجعه","segs":[["matn","والاستثناءُ تكلَّم بالباقي بعد الثنيا. وإذا تعقب الاستثناء جُملاً متعاطفةً صُرِف إلى الأخيرةِ"]],"q":"ما حقيقة الاستثناء؟ وإلامَ يُصرف إذا تعقّب جملاً متعاطفة؟"},{"id":"u59_5","label":"بيان الضرورة","segs":[["matn","للضَّرورة: وهو نوعُ بيان يقع بما لم يوضع للبيان بالنُّطق، وهو البيان بالسكوت"]],"q":"ما بيان الضرورة؟"},{"id":"u59_6","label":"تعريف النسخ","segs":[["matn","للتَّبديل: وهو النَّسخُ، وهو اصطلاحاً: أن يَدُلَّ على خلافِ حكمِ شرعيٍّ دليلٌ شرعيٌّ متراخٍ، وهذا في حَقّ البَشَر. ويُجْعَلُ في حَقِّ الشَّارع بياناً لانتهاء مدّة الحكم المطلق عن تأبيدٍ أو تأقيت المعلوم عند الله"]],"q":"ما تعريف النسخ اصطلاحاً في حقِّ البشر وفي حقِّ الشارع؟"},{"id":"u59_7","label":"شرط النسخ ومحله","segs":[["matn","وشَرْطُ جواز النَّسخ: التَّمكّنُ من عقدِ القلبِ عندنا، ومحَلُّه: حكمٌ يحتملُ الوجودَ والعدمَ في نفسِه."]],"q":"ما شرط جواز النسخ عندنا؟ وما محلُّه؟"},{"id":"u59_8","label":"ما يصلح ناسخاً","segs":[["matn","والقياسُ لا يصلح ناسخاً للكتاب والسُّنة؛ والإجماعُ لا يصلح ناسخاً عند الجمهور، فيجوز نسخُ كلٍّ من الكتابِ والسُّنَّةِ بالآخر"]],"q":"هل يصلح القياس والإجماع ناسخين؟ وهل يُنسخ الكتاب بالسنة؟"},{"id":"u59_9","label":"أقسام المنسوخ","segs":[["matn","وأقسام المنسوخ: ١. نسخُ الحكم والتِّلاوة جميعاً، ٢. نسخ التِّلاوة مع بقاء الحكم، ٣. نسخُ الحكم وبقاءُ التِّلاوة ٤. نسخ وصفِ الحكم مع بقاءِ أصلِه"]],"q":"ما أقسام المنسوخ؟"}]},{"id":"u60","title":"الفصل الخامس شرائع من قبلنا","group":"الباب الثَّاني الكتاب","units":[{"id":"u60_1","label":"المراد بشرائع من قبلنا","segs":[["matn","شرائع من قبلنا: المراد به الأحكام الفرعيّة التي شُرعت على الأُمم السَّابقة ونزلت على أنبيائهم"]],"q":"ما المراد بشرائع من قبلنا؟"},{"id":"u60_2","label":"ما لم يصل إلينا بطريق معتبر","segs":[["matn","إن لم يصل إلينا أو وصل على لسان واحدٍ من أفرادِ تلك الأُمم، فهذا النَّوع لا يلزمنا اتفاقاً"]],"q":"ما حكم ما لم يصل إلينا من شرائع من قبلنا أو نقله أحدهم؟"},{"id":"u60_3","label":"ما ورد منسوخاً أو منكراً","segs":[["matn","إن ورد منسوخاً في شريعتنا، أو على سبيل الإنكار، فإنَّه لا يلزمنا العمل به وليس شرعاً لنا اتفاقاً"]],"q":"ما حكم ما ورد منسوخاً في شريعتنا أو على سبيل الإنكار؟"},{"id":"u60_4","label":"ما دل الدليل على لزومه","segs":[["matn","إن ورد إلينا وقد دلَّ الدَّليل على أننا مُكَلَّفون به، وملزمون بالأخذ به، فهو شرعٌ لنا، وملزمون به اتفاقاً"]],"q":"ما حكم ما دلَّ الدليل على أننا مكلَّفون به من شرائع من قبلنا؟"},{"id":"u60_5","label":"ما قصه الشرع بلا نكير","segs":[["matn","إن قَصَّه القرآن أو السُّنّة ولم يقترن به ما يدلُّ على نسخِهِ وإنكاره أو على لزوم فعله علينا، ولم يرد في شرعنا ما يخالفه، فإنَّه يلزمُنا على أنَّه شريعة رسولنا ﷺ"]],"q":"ما حكم ما قصَّه القرآن أو السنة من شرائع من قبلنا بلا نكير؟"}]},{"id":"u62","title":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u62_1","label":"تعريف السنة لغة واصطلاحاً","segs":[["matn","السُّنة لغةً: الطريقة، وعند الأصوليين: قول النَّبي ﷺ وفعله وتقريره وقول الصَّحابي رضي الله عنه وفعله."]],"q":"ما تعريف السنة لغةً وعند الأصوليين؟"},{"id":"u62_2","label":"السنة عند الفقهاء","segs":[["matn","السُّنة: عند الفقهاء: هي ما واظب عليه النَّبي ﷺ مع التَّرك أحياناً بلا عذر."]],"q":"ما تعريف السنة عند الفقهاء؟"},{"id":"u62_3","label":"السنة القولية والفعلية","segs":[["matn","فتكون على عدّة صور: ١. سُنَّة قولية: وهي الأحاديث التي قالها النَّبي ﷺ ٢. سُنَّة فعلية: وهي الأعمال التي قام بها النَّبي ﷺ على سبيل التَّشريع ولم يكن من خصائصه"]],"q":"ما السنة القولية والسنة الفعلية؟"},{"id":"u62_4","label":"السنة التقريرية وسنة الصحابة","segs":[["matn","٣. سُنّة تقريرية: بأن يرى ﷺ من أُمّته فعلاً أو قولاً فلم يُنكر النَّبيّ ﷺ وسكت، فهذا تقرير منه ﷺ، لكن يشترط أن لا يكون سهواً، ولا طبعاً، ولا خاصة ٤. سُنَّة الصَّحابة رضي الله عنهم: بأن لم يواظب عليها رسول الله ﷺ، بل واظب عليها الصَّحابة رضي الله عنهم"]],"q":"ما السنة التقريرية وشروطها؟ وما سنة الصحابة رضي الله عنهم؟"},{"id":"u62_5","label":"خلاف الحنفية في قول الصحابي","segs":[["matn","واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي: ١. إنَّ تقليدَ الصَّحابيّ رضي الله عنه واجبٌ يُترك بقوله القياس، ٢. لا يجوز تقليد الصَّحابي رضي الله عنه إلا فيما لا يُدرك بالقياس، فالاختلاف في تقديم الصَّحابيّ على القياس، والاتفاق في تقليدِه فيما لا يُعقل بالقياس."]],"q":"ما أقوال الحنفية في حجية قول الصحابي رضي الله عنه؟"}]},{"id":"u63","title":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u63_1","label":"مراتب الاتصال بالنبي ﷺ","segs":[["matn","مراتب الاتصال بالنَّبي ﷺ، وهي: ١. اتصالٌ كامل بلا شبهة: أي لا صورةً ولا معنى، وهو المتواتر، ٢. اتصالٌ فيه ضربُ شبهة صورة، وهو المشهور، ٣. اتصالٌ فيه شبهةٌ صورةً ومعنى، وهو الآحاد،"]],"q":"ما مراتب الاتصال بالنبي ﷺ؟"},{"id":"u63_2","label":"المشهور قسم حنفي مستقل","segs":[["matn","فمراعاتُهم لجانبِ المعنى في الاتصال والقَبول والتَّصحيح جَعَلَت عندهم قسماً مستقلاً لم يوجد عند المُحَدِّثين، وهو المشهور"]],"q":"لماذا كان المشهور قسماً مستقلاً عند الحنفية دون المحدِّثين؟"}]},{"id":"u64","title":"المطلب الأول: السُّنة المتواترة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u64_1","label":"التواتر لغة","segs":[["matn","والتَّواتر لغةً: التتابع، يُقال: تواترت الخيل إذا جاءت يتبع بعضها بعضاً."]],"q":"ما معنى التواتر لغةً مع التمثيل؟"},{"id":"u64_2","label":"تعريف التواتر اللفظي","segs":[["matn","تواتر الإسناد «اللفظي»: ما بلغت رُواتُه في الكثرة مبلغاً أحالت العادة تواطؤهم على الكذب، ويدوم هذا، فيكون أَوّله كآخِره، ووسَطُه كطرفَيْه"]],"q":"ما تعريف تواتر الإسناد «اللفظي»؟"},{"id":"u64_3","label":"علامة المتواتر وحكمه","segs":[["matn","وعلامة المتواتر حصول العلم الضَّروري، وحكمه عند جمهور الأصوليين والمُحَدِّثين: هو أنَّ العلم الحاصل به علم اليقين كالعيان الذي يوجبه الحس من البصر والسَّمع"]],"q":"ما علامة المتواتر؟ وما حكمه عند الجمهور؟"},{"id":"u64_4","label":"التواتر المعنوي وحكمه","segs":[["matn","تواتر القدر المشترك «المعنوي»: وهو أن يكون مضمون ما مذكوراً في كثيرٍ من الآحاد، كتواترِ المعجزة، فإنَّ مفرداتها وإن كانت آحاداً، لكنَّ القدر المشترك متواتر قطعاً، وحكمه: إن كان ضرورياً فيكفر جاحدُه، وإن كان نظرياً فلا"]],"q":"ما التواتر المعنوي مع التمثيل؟ وما حكمه؟"},{"id":"u64_5","label":"التواتر الطبقي وحكمه","segs":[["matn","التَّواترُ الطَّبقي «التَّوارث المدرسي»: وهو أن تأخذَ طبقةٌ عن طبقةٍ بلا إسناد، والقرآنُ متواترٌ بهذا التَّواتر؛ وحكم التَّواتر الطَّبقي: أنَّه يكفر جاحده على أحد نوعي هذا القسم، وهو ما كان تواتره ظاهراً من طبقة إلى طبقة بدون اعتماد على إسناد، بحيث صار معلوماً من الدِّين بالضَّرورة"]],"q":"ما التواتر الطبقي؟ وما حكمه؟"},{"id":"u64_6","label":"التواتر العملي وحكمه","segs":[["matn","التَّواترُ العمليُّ: وهو أن يتواتر العمل على أمرٍ ما بحيث يستحيل تكذيبهم، وحكمه: التَّواتر العملي يوجب العمل قطعاً، فيجوز نسخ الكتاب العزيز به، وجاحدُ المتواتر في ظهورِ العملِ لا يكفر"]],"q":"ما التواتر العملي؟ وما حكمه؟"}],"sup":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ"},{"id":"u65","title":"المطلب الثَّاني: السُّنة المشهورة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u65_1","label":"مدار الشذوذ عند الحنفية","segs":[["matn","فمدارُ الشُّذوذِ عندهم على آحادية نقله، وعدم القَبول له، ومُخالفته لما هو أقوى منه."]],"q":"على أيِّ شيء مدار الشذوذ عند الحنفية؟"},{"id":"u65_2","label":"تعريف المشهور","segs":[["matn","المشهور: سُمِّيَ بذلك؛ لوضوحه، ويُسَمَّى المستفيض، واصطلاحاً: ما كان من الآحاد في الأصل، ثُمَّ انتشر فصار ينقلُه قومٌ لا يتوهم تواطؤهم على الكذب، وهم القرن الثَّاني بعد الصَّحابة رضي الله عنهم، ومَن بعدهم"]],"q":"ما تعريف المشهور؟ ولماذا سُمِّي بذلك؟"},{"id":"u65_3","label":"زمن الاشتهار المعتبر","segs":[["matn","وإنَّما كان الاعتبار للاشتهار في القرن الثَّاني والثَّالث، ولا عبرة للاشتهار في القرون التي بعد القرون الثَّلاثة"]],"q":"في أيِّ القرون يُعتبر الاشتهار؟"},{"id":"u65_4","label":"التعريف المختار للمشهور","segs":[["matn","السُّنة المشهورة: سُنَّة الآحاد إذا تأيّدت بعمل الصَّحابة رضي الله عنهم والتَّابعين وقَبولهم، وبعبارة أُخرى: هو حديث الآحاد الذي تَلَقَّاه السَّلف بالقَبول"]],"q":"ما التعريف المختار للسنة المشهورة؟"},{"id":"u65_5","label":"القولان في حكم المشهور","segs":[["matn","حكم المشهور: أ. أَنَّه مثل المتواتر، فيثبت به علم اليقين لكن بطريق الاستدلال لا بطريق الضَّرورة؛ ب. أَنَّه يوجب علم طمأنينة لا علم يقين،"]],"q":"ما القولان في حكم المشهور؟"},{"id":"u65_6","label":"رتبة المشهور وحكم جاحده","segs":[["matn","المشهور: فكان دون المتواتر وفوق خبر الواحد، حتى جازت الزِّيادة به على كتاب الله تعالى ونصَّ شمسُ الأئمة السَّرَخسيُّ على أنَّ جاحدَه لا يَكفر بالاتفاق"]],"q":"ما رتبة المشهور؟ وما حكم جاحده؟"}],"sup":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ"},{"id":"u66","title":"المطلب الثَّالث: سُنَّة الآحاد","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u66_1","label":"تعريف الآحاد","segs":[["matn","سُنَّة الآحاد: وهو كل خبر يرويه الواحد أو الاثنان فصاعداً، لا عبرة للعدد فيه بعد أن يكون دون المشهور والمتواتر"]],"q":"ما تعريف سنة الآحاد؟"},{"id":"u66_2","label":"حكم الآحاد","segs":[["matn","وحكم الآحاد: إفادة غلبة الظَّنِّ بمدلولها، لا اليقين ولا الطَّمأنينة، وهي كافيةٌ في وجوب العمل دون العلم القطعي"]],"q":"ما حكم سنة الآحاد؟"}],"sup":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ"},{"id":"u68","title":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u68_1","label":"الصحابي الفقيه وحكم خبره","segs":[["matn","الأول: معروف، وهو نوعان: ١. مَن كان معروفاً بالفقه والرَّأي في الاجتهاد، وهم كبار المجتهدين من الصَّحابة رضي الله عنهم وحكم خبرهم: وجوب العمل به، سواء كان موافقاً للقياس أو مخالفاً له"]],"q":"ما الصحابي المعروف بالفقه والرأي؟ وما حكم خبره؟"},{"id":"u68_2","label":"الصحابي العدل غير الفقيه","segs":[["matn","٢. مَن كان معروفاً بالعدالة وحسن الضَّبط والحفظ، ولكنَّهم لم يبلغوا درجةَ كبار المجتهدين من الصَّحابة رضي الله عنهم، وحكم خبرهم: إن وافق القياس عُمِل به، وإن خالفه لم يترك إلا إن أدى العمل به إلى انسداد باب الرَّأي، فحينئذ يترك ويُعمل بالقياس."]],"q":"ما حكم خبر الصحابي المعروف بالعدالة والضبط غير المجتهد؟"},{"id":"u68_3","label":"الصحابي المجهول","segs":[["matn","الثاني: مجهول: وهم مَن لم يشتهروا بطول الصُّحبة مع رسول الله ﷺ، وإنَّما عُرِف بما روى من حديث أو حديثين، ورواية هذا النَّوع على خمسة أوجه:"]],"q":"مَن الصحابي المجهول؟ وعلى كم وجهٍ روايته؟"},{"id":"u68_4","label":"أوجه المجهول المقبولة","segs":[["matn","١. أن يشتهر خبره؛ لقَبول الفقهاء روايته والرِّواية عنه. ٢. أن يسكت الفقهاء عن الطَّعن في روايته بعدما اشتهرت. ٣. أن يختلف الفقهاء في الطَّعن في روايته. وحكم خبره: وجوب العمل به مطلقاً"]],"q":"ما أوجه رواية المجهول التي يجب العمل بها؟"},{"id":"u68_5","label":"أوجه المجهول غير الملزمة","segs":[["matn","٤. أن يطعنوا في روايته من غير خلاف بين الفقهاء في ذلك. وحكم خبره: لا يجوز العمل بروايته؛ ٥. أن لا تظهر روايته ولا الطَّعن فيها بين الفقهاء، وحكم خبره: لا يجب العمل به، ولكن يجوز العمل به إذا وافق القياس"]],"q":"ما وجها رواية المجهول اللذان لا يجب العمل بهما؟ وما حكمهما؟"}],"sup":"المبحث الثَّاني رُواة الأحاديث"},{"id":"u69","title":"المطلب الثَّاني: شروط الرَّاوي","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u69_1","label":"شروط الراوي","segs":[["matn","شروط الرَّاوي: ١. العقل ٢. الضَّبط ٣. الإسلام ٤. العدالة"]],"q":"ما شروط الراوي؟"},{"id":"u69_2","label":"المعتبر في شرط العقل","segs":[["matn","العقل: والمعتبر هو عقل البالغ دون القاصر: كالصَّبيّ والمعتوه والمجنون، وأما إذا كان السَّماع قبل البلوغ والرِّواية بعد البلوغ يُقبل قول الصَّبيّ فيه"]],"q":"ما المعتبر في شرط العقل للراوي؟"},{"id":"u69_3","label":"حد الضبط","segs":[["matn","وحدُّ الضَّبط: هو سماع الكلام كما يحقّ سماعه من أوَّله إلى آخره بتمام الكلمات والهيئة التَّركيبة، ثم فهمه بمعناه الذي به لغوياً كان أو شرعياً، ثمّ حفظه ببذل المجهود له، ثمّ الثَّبات عليه، وهذا كلُّه إلى حين أدائه وتبليغه"]],"q":"ما حدُّ الضبط في الراوي؟"},{"id":"u69_4","label":"حد العدالة","segs":[["matn","العدالة: وحدُّها هنا: رجحان جهة الدِّين والعقل على طريق الهوى والشَّهوة حتى إذا ارتكب كبيرةً أو أصرَّ على صغيرةٍ سقطت عدالته. والمجهول من القرونِ الثَّلاثةِ عدلٌ بتعديل صاحب الشَّرع إيّاه ما لم يتبيَّن منه ما يُزيل عدالته"]],"q":"ما حدُّ العدالة؟ وما حكم المجهول من القرون الثلاثة؟"},{"id":"u69_5","label":"عدالة الصحابة ومرادها","segs":[["matn","عدالة الصَّحابة: أنَّ الصَّحابةَ كلَّهم عدول، كبيرهم وصغيرهم، قبل زمان الفتن وبعدَه، ومراد المُحَدِّثين من قولهم الصَّحابة رضي الله عنهم كلّهم عدول: هو التَّجنُّب عن تَعَمُّدِ الكذب في الرِّواية"]],"q":"ما القول في عدالة الصحابة؟ وما مراد المحدِّثين بها؟"}],"sup":"المبحث الثَّاني رُواة الأحاديث"},{"id":"u70","title":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u70_1","label":"صورتا انقطاع الحديث","segs":[["matn","انقطاع الحديث: وهذا الانقطاع على صورتين: ظاهرة؛ بأن يفقد فيه أحد رجال الإسناد، وباطنة؛ بأن يلحق الحديث طعنٌ يورث الانقطاع"]],"q":"ما صورتا انقطاع الحديث؟"}]},{"id":"u71","title":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u71_1","label":"تعريف المرسل","segs":[["matn","والمُرْسَل لغةً: من الإرسال، وهو الإطلاق، واصطلاحاً: عند الفقهاء والأصوليين قول الإمام الثِّقة: قال ﷺ مع حذف من السَّند، أو ترك الواسطة بين الرَّاوي والمروي عنه"]],"q":"ما تعريف المرسل لغةً واصطلاحاً عند الفقهاء والأصوليين؟"},{"id":"u71_2","label":"المرسل بين الفقهاء والمحدثين","segs":[["matn","وبهذا يظهر الفرق في إطلاقِ مصطلحِ المُرْسَلِ بين الفقهاءِ والمُحَدِّثين، بأنَّ الفقهاءَ يقصدون به كلَّ حديثٍ رُفِع إلى النَّبيِّ ﷺ لم يذكر سنده، والمُحَدِّثين يَخُصُّونه بعدم ذكر الصَّحابي الرَّاوي للحديث من قبل التَّابعي فقط"]],"q":"ما الفرق في إطلاق المرسل بين الفقهاء والمحدِّثين؟"},{"id":"u71_3","label":"أقسام المرسل عند الفقهاء","segs":[["matn","المرسل: فهو على أقسام عند الفقهاء، وهي: ١. مُرْسَل الصَّحابي رضي الله عنه، وهو مقبول بالإجماع. ٢. مُرْسَل من القرن الثَّاني والثَّالث، فإنَّه مقبولٌ عند الفقهاء ٣. مُرْسَلُ غيرُ القرون الثَّلاثة الأولى ٤. مرسلٌ أُرسل من وجهٍ، وأُسند من وجهٍ، فهو مقبولٌ عند الأكثر"]],"q":"ما أقسام المرسل عند الفقهاء وحكم كلٍّ؟"},{"id":"u71_4","label":"موقف الحنفية من المرسل","segs":[["matn","ونخلص ممَّا سَبَقَ: إلى قَبولِ السَّادة الحنفيّة للمُرْسَل، وعدم التَّفريق بينه وبين المُسْنَد إذا كان مرسلُه ثقةٌ ولا يروي إلا عن ثقةٍ، لاسيما في القرونِ الثَّلاثةِ الأُولى، وأمّا بعدها فالمشهور عدم قَبوله"]],"q":"ما موقف الحنفية من المرسل؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u72","title":"المطلب الثَّاني: الباطن","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u72_1","label":"المقصود بالانقطاع الباطن","segs":[["matn","والمقصود بالباطن ما حصل فيه انقطاع خفي في الحديث، بحيث يكون في اتصال الحديث بالنَّبي ﷺ نظرٌ من جهةِ مشكلةٍ في الرَّاوي، أو معارضةِ الحديث لما هو أقوى منه، أو مخالفةِ الحديث للعمل"]],"q":"ما المقصود بالانقطاع الباطن؟"},{"id":"u72_2","label":"نقصان الناقل وحكمه","segs":[["matn","أولاً: نقصان في النَّاقل: وهو أن يكون الاتصال فيه ظاهراً، ولكن وقع الخلل بوجه آخر، وهو فقد شرائط الرَّاوي وحكمه: أن لا يُقبل خبر الكافر والفاسق والصَّبي والمعتوه الذي اشتدت غفلته"]],"q":"ما نقصان الناقل؟ وما حكمه؟"},{"id":"u72_3","label":"شرط الطعن المعتبر","segs":[["matn","ولا يُعتبر الطَّعن في الرَّاوي إن لم يكن مُفَسَّراً من أئمة الحديث بما هو جرح متفق عليه، بخلاف الطَّعن المبهم، فإنَّه لا يجرح الرَّاوي؛ ولا بدَّ أن يكون الجرح المفسَّرُ المعتبرُ صادراً من طاعن مشتهر بالنَّصيحة دون التَّعصب والعداوة"]],"q":"ما شرط الطعن المعتبر في الراوي؟"},{"id":"u72_4","label":"طعون غير مقبولة","segs":[["matn","فلا يُقبل الطَّعن فيما يلي مثلاً: أ. التَّلبيس ب. الإرسال ج. ركض الدَّابة د. المزاح هـ. حداثة السِّنّ و. عدم الاعتبار بالرِّواية ز. استكثار مسائل الفقه"]],"q":"ما الطعون التي لا تُقبل في الراوي؟"},{"id":"u72_5","label":"معارضة الأقوى","segs":[["matn","ثانياً: معارضة الأقوى: وهو ما وقع فيه الخلل لمعارضته لدليل فوقه بالعَرْض عليه؛ لأنَّ معارضة الآحاد لما هو أَقوى من حيث قوَّة النَّقل يندرج تحتها معارضته للقرآن والحديث المتواتر والحديث المشهور"]],"q":"ما معارضة الأقوى؟ وما الذي يندرج تحتها؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u73","title":"الأَوَّل: مخالفةُ الآحاد للقرآن","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u73_1","label":"الآحاد المعارض لعموم القرآن","segs":[["matn","ومعارضة ظاهر القرآن أو عمومه؛ بأن يكون خبرُ الواحد معارضاً لعموم الكتاب أو ظاهره سبب للاعتذار عن العمل به؛ لأنَّ الحنفية لا يرون تخصيص عموم القرآن أو نسخه بالآحاد"]],"q":"ما حكم خبر الواحد المعارض لعموم القرآن أو ظاهره؟ ولماذا؟"},{"id":"u73_2","label":"حكم الفاتحة عند الحنفية","segs":[["matn","فقُدِّمَ القرآن، وكان حكم الفاتحة الوجوب لا الفرضية، وإنَّما فَرْضُ القراءة قراءة آية من القرآن"]],"q":"ما حكم قراءة الفاتحة عند الحنفية؟ وما فرض القراءة؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u75","title":"الثَّالث: معارضة الآحاد للحديث المشهور","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u75_1","label":"المقصود بمخالفة الحديث للعمل","segs":[["matn","ثالثاً: مخالفة الحديث للعمل: ويقصد بالمخالفة للعمل أن يخالف راوي الحديث ما رواه في عمله أو فتياه، أو يخالف الصَّحابة رضي الله عنهم فيفتون أو يعملون بغيره، أو يعرض الصَّحابة رضي الله عنهم عن العمل بالحديث، أو يترك العمل بالآحاد لوروده في عموم البلوى"]],"q":"ما المقصود بمخالفة الحديث للعمل؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u76","title":"الأولى: مخالفة الرَّاوي لمرويه","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u76_1","label":"إنكار الراوي روايته","segs":[["matn","مخالفة الرَّاوي لمرويه: ١. إنكار راوي الحديث الرِّوايةَ، فإن كان إنكار جاحد، بأن يقول: كذب عليَّ، أو ما رويت هذا، فإنَّه يسقط العمل بالحديث اتفاقاً، وإن كان إنكارَ مُتوقِّف؛ ففيه خلافٌ: فعند الكرخيّ وجماعة وهو مختارُ أبي حنيفة وأبي يوسف: يسقط العمل به، وقال محمد: لا يسقط"]],"q":"ما حكم إنكار الراوي روايته جحوداً أو توقفاً؟"},{"id":"u76_2","label":"عمل الراوي بخلاف مرويه","segs":[["matn","٢. عمل راوي الحديث بخلاف مرويه، وهذا يسقط اعتباره، بل العبرة عند الحنفية بما رأى لا بما روى؛ لأنَّ الرَّاوي العدل المؤتمن إذا رَوَى حديثاً عن رسول الله ﷺ وعمل بخلافه، دلَّ ذلك على شيءٍ ثبت عنده من نسخٍ أو مُعارضةٍ أو تخصيصٍ"]],"q":"ما حكم عمل الراوي بخلاف مرويه؟ ولماذا؟"},{"id":"u76_3","label":"تعيين الراوي بعض المحتملات","segs":[["matn","٣. تعيينُ الرَّاوي بعض محتملات المروي: بأن كان عامّاً فعمل بخصوصه، أو مشتركاً فعمل بأحد معنييه، فإنَّه لا يَمنع العمل به؛ لأنَّه تأويل لا حجر"]],"q":"ما حكم تعيين الراوي بعض محتملات المروي؟ ولماذا؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u77","title":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u77_1","label":"مخالفة الصحابة للحديث","segs":[["matn","إن خالف بعضِ الصَّحابة رضي الله عنهم العملَ بالحديث إذا كان ظاهراً لا يحتمل الخفاءَ عليهم يُورث الطَّعن فيه؛ لذلك قالوا: عمل صحابيّ آخر بخلافه يُسقطه عن درجة الاعتبار، بخلاف عمل الصَّحابي نفسه بخلاف مرويه، فإنَّه يجعله غير معتبر أصلاً"]],"q":"ما أثر مخالفة بعض الصحابة رضي الله عنهم العمل بالحديث؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u78","title":"الثَّالثة: إعراضُ الصَّحابة رضي الله عنهم عن الحديث","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u78_1","label":"إعراض الصحابة عن الحديث","segs":[["matn","إنَّ أعرض الأئمةِ من الصَّدرِ الأَوّل عن الحديث؛ بأن تركوا المحاجّة به عند الحاجة، فإنَّه يعتبر رداً له؛ فإنَّهم إذا تركوا المحاجة به مع وقوع الاختلاف فيما بينهم يكون مردوداً عند بعض الحنفية المتقدِّمين وعامَّة المتأخِّرين"]],"q":"ما حكم إعراض أئمة الصدر الأول عن الحديث؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u79","title":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى»","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u79_1","label":"تعريف ما يعم به البلوى","segs":[["matn","إنَّ معنى اصطلاح الحادثة المشتهرة أو ما يعمّ به البلوى: هو ما تمسُّ الحاجةُ إليه في عمومِ الأحوال، أو يحتاج إليه الكلُّ حاجةً متأكدةً مع كثرةِ تكرُّرِه"]],"q":"ما معنى ما يعمُّ به البلوى اصطلاحاً؟"},{"id":"u79_2","label":"حكم الآحاد فيما يعم به البلوى","segs":[["matn","فما كان من أحكام الشَّريعة بالنَّاس حاجةٌ إلى معرفتِهِ، فسبيلُ ثبوته الاستفاضة والخبر الموجب للعلم، وغيرُ جائز إثباتُ مثلِهِ بأخبارِ الآحاد"]],"q":"ما سبيل ثبوت ما بالناس حاجة إلى معرفته من الأحكام؟"},{"id":"u79_3","label":"قبول الآحاد في غير الوجوب","segs":[["matn","فإنَّ خبر الآحاد إذا ورد في غير الوجوب والحظر: كالمسنون والمباح ونحوهما، فإنَّه يكون مقبولاً عند الحنفية"]],"q":"ما حكم خبر الآحاد الوارد في غير الوجوب والحظر عند الحنفية؟"},{"id":"u79_4","label":"الخلاف في عموم البلوى","segs":[["matn","فنُسِب للكَرخيِّ القولُ بأنَّ خبرَ الواحد إذا وَرَدَ موجباً للعمل فيما يَعمُّ به البَلوى لا يُقبل، وهو مُختار المتأخِّرين، وأمّا عند عامَّةِ الأُصوليين: فخبرُ الواحد فيما تعمُّ به البلوى مقبول إذا صَحّ سندُه"]],"q":"ما الخلاف في قبول خبر الواحد فيما يعمُّ به البلوى؟"},{"id":"u79_5","label":"اشتراط فقه الراوي","segs":[["matn","مخالفة الحديث للقياس: إنَّ اشتراط فقه الرَّاوي «اجتهاد الرَّاوي» لم ينصّ عليه أئمةُ المذهب، بل هو تخريج عمّا ورد عنهم من فروع، واختلف أصوليو المذهب في هذا التَّخريج على قولين: ١. اشتراط فقه الرَّاوي؛ لتقديم خبره على القياس ٢. لا يشترط فقه الرَّاوي لتقديم خبره على القياس"]],"q":"ما القولان في اشتراط فقه الراوي لتقديم خبره على القياس؟"},{"id":"u79_6","label":"تقديم خبر الواحد على القياس","segs":[["matn","ولم يُنقل القول بتقديم القياس على خبر غير الفقيه عن أصحابنا، بل المنقول عنهم أنَّ خبر الواحد مقدَّمٌ على القياس ولم ينقل التَّفضيل"]],"q":"ما المنقول عن أصحابنا في تقديم خبر الواحد على القياس؟"}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u81","title":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u81_1","label":"خبر الواحد في العبادات والديانات","segs":[["matn","إن كان في حقوق الله: أ. إن كان في العبادات يقبل؛ وما كان من الدِّيانات: كالإخبار بطهارة الماء ونجاسته، فيثبت بخبر الواحد العدل أن هذا الماء طاهر أو نجس؛ لكن إن أخبر بها الفاسق أو المستور يتحرى"]],"q":"ما حكم خبر الواحد في العبادات والديانات؟"},{"id":"u81_2","label":"خبر الصبي والكافر في الديانات","segs":[["matn","وأما أخبار الصَّبي والمعتوه والكافر، فلا تُقبل في الدِّيانات: كالإخبار عن طهارةِ الماء ونجاسته، ولا يجب التَّحرّي"]],"q":"ما حكم أخبار الصبي والمعتوه والكافر في الديانات؟"},{"id":"u81_3","label":"خبر الواحد في العقوبات","segs":[["matn","ب. إن كان في العقوبات، فلا تثبت الحدود من حديث الآحاد عند الكرخي؛ لأنَّ في اتصاله إلى رسول الله ﷺ شبهة، والحدود تندرئ بها، وقال الجصاص: تثبت الحدود بخبر الواحد"]],"q":"هل تثبت الحدود بخبر الآحاد؟ وما الأقوال فيه؟"},{"id":"u81_4","label":"حقوق العباد: الإلزام المحض","segs":[["matn","الثَّاني: إن كان في حقوق العباد، فله ثلاث صور: أ. إن كان مما فيه إلزامٌ محضٌ: فإنَّه يشترط فيه سائر شرائط الأخبار من العقل والعدالة والضَّبط والإسلام مع العدد بأن يكون اثنين، والتَّلفظ بقوله: أشهد، وتكون له الولاية بالحرية"]],"q":"ما يُشترط في خبر حقوق العباد الذي فيه إلزام محض؟"},{"id":"u81_5","label":"ما لا إلزام فيه أصلاً","segs":[["matn","ب. إن لم يكن فيه إلزام أصلاً؛ كخبر الوكالة والمضاربة والرِّسالة في الهدايا ونحوها، فيثبت الخبر بشرط التَّمييز دون العدالة وإن كان عبداً أو كافراً أو فاسقاً"]],"q":"ما يُشترط في الخبر الذي لا إلزام فيه أصلاً مع التمثيل؟"},{"id":"u81_6","label":"ما فيه إلزام من وجه","segs":[["matn","ج. إن كان فيه إلزام من وجه دون وجه: كخبر عزل الوكيل، وحجر المأذون، فإنَّه يشترط فيه أحد شطري الشَّهادة من العدد أو العدالة؛ إذ لا بدّ أن يكون المُخبر اثنين أو واحداً عدلاً"]],"q":"ما يُشترط في الخبر الذي فيه إلزام من وجه مع التمثيل؟"}],"sup":"المبحث الرَّابع حجية خبر الآحاد وأقسامه"},{"id":"u82","title":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u82_1","label":"ما يقطع بصدقه أو كذبه","segs":[["matn","أقسام الخبر: أولاً: قسم يحيط العلم بصدق الخبر: كخبر الأنبياء ﷺ لعصمتهم، وحكمه: اعتقاد الحقية والائتمار، ثانياً: قسم يحيط العلم بكذبه: وحكمه: اعتقاد البطلان، والاشتغال برده"]],"q":"ما حكم الخبر المقطوع بصدقه والمقطوع بكذبه؟"},{"id":"u82_2","label":"المحتمل والراجح من الأخبار","segs":[["matn","ثالثاً: قسم يحتمل الصِّدق والكذب على السَّواء: كخبر الفاسق، وحكمه التَّوقف فيه؛ رابعاً: قسم يرجح أحد احتماليه الصِّدق على الكذب: كخبر العدل المستجمع لشرائط الرِّواية، وحكمه: العمل به لا العلم والاعتقاد بحقيقته"]],"q":"ما حكم الخبر المحتمل على السواء والراجح صدقه مع التمثيل؟"},{"id":"u82_3","label":"أطراف خبر العدل الثلاثة","segs":[["matn","خبر العدل: وهذا القسم له ثلاثة أطراف: ١. طرف السَّماع، بأن يسمع الحديث من المُحَدِّث أولاً ٢. طرف الحفظ، بأن يحفظ بعد ذلك من أوله إلى آخره ٣. طرفُ الأداء، بأن يلقيه إلى الآخر لتفرغ ذمته"]],"q":"ما أطراف خبر العدل الثلاثة؟"},{"id":"u82_4","label":"صور العزيمة في السماع","segs":[["matn","طرف السَّماع: والعزيمة فيه لها صور: أ. أن يقرأ على المُحَدِّث من كتاب أو حفظ، وهو يسمعه، ب. أن يقرأ المُحَدِّث عليك من كتاب أو حفظ وأنت تسمعه، ج. أن يكتب المُحَدِّث إليك كتاباً على رسم الكتب د. أن يرسل المُحَدِّث رسولاً"]],"q":"ما صور العزيمة في طرف السماع؟"},{"id":"u82_5","label":"صور الرخصة في السماع","segs":[["matn","طرف السَّماع: والرُّخصة فيه لها صور: أ. الإجازة: بأن يقول المُحَدِّث لغيره: أجزت لك أن تروي عني هذا الكتاب ب. المناولة: بأن يعطي الشَّيخ كتاب سماعه بيده إلى المستفيد، فهو لا يصح بدون الإجازة، والإجازة تصح بدون المناولة"]],"q":"ما صور الرخصة في طرف السماع؟"},{"id":"u82_6","label":"العزيمة والرخصة في الحفظ","segs":[["matn","طرف الحفظ: والعزيمة فيه: وهو أن يحفظ المسموع من وقت السَّماع إلى وقت الأداء، ولم يعتمد على الكتاب. والرُّخصة فيه: وهو أن يعتمد الكتاب فإن نظر فيه وتذكَّر ما كان مسموعاً له صار كأنَّه حفظه من وقت السَّماع إلى وقت الأداء؛ أما إن لم يتذكَّر من الخط شيئاً فلا تحل له الرِّواية"]],"q":"ما العزيمة والرخصة في طرف الحفظ؟"},{"id":"u82_7","label":"العزيمة والرخصة في الأداء","segs":[["matn","طرفُ الأداء: والعزيمة فيه: وهو أن يؤدي على الوجه الذي سمع بلفظه ومعناه، والرُّخصة فيه: وهو أن ينقله بمعناه: أي بلفظ آخر يؤدّي معنى الحديث، وهذا صحيح عند العامَّة"]],"q":"ما العزيمة والرخصة في طرف الأداء؟"},{"id":"u82_8","label":"من يجوز له النقل بالمعنى","segs":[["matn","طرفُ الأداء: أ. إن كان محكماً لا يحتمل إلا معنى واحداً، يجوز نقله بالمعنى لمن له معرفة في وجوه اللغة ب. إن كان ظاهراً معلوماً يحتمل غير معناه؛ بأن كان عاماً يحتمل الخصوص، أو حقيقةً يحتمل المجاز، فلا يجوز نقله بالمعنى إلا للفقيه المجتهد"]],"q":"متى يجوز نقل الحديث بالمعنى؟ ولمن؟"},{"id":"u82_9","label":"ما لا يجوز نقله بالمعنى","segs":[["matn","ج. إن كان من جوامع الكلم، بأن كان لفظه وجيزاً وتحته معان كثيرة، أو كان من المشكل أو المشترك أو المُجْمل، فإنَّه لا يجوز نقله بالمعنى للمجتهد وغيره"]],"q":"ما الذي لا يجوز نقله بالمعنى؟"}],"sup":"المبحث الرَّابع حجية خبر الآحاد وأقسامه"},{"id":"u83","title":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u83_1","label":"حجية السنة","segs":[["matn","أولاً: حجية السُّنة الشَّريفة: فإنَّه يجب العمل بالسُّنة كما يجب العمل بالكتاب"]],"q":"ما حكم العمل بالسنة الشريفة؟"},{"id":"u83_2","label":"منزلة السنة في التشريع","segs":[["matn","ثانياً: منزلة السُّنة في التَّشريع: اتفقت الأُمَّة على أنَّ السُّنةَ تأتي بالاحتجاج بها بعد كتاب الله فإن وجد الحكم في كتاب الله تعالى وجب الوقوف عنده، وان لم يوجد فُتِّش عنه في سنة رسول الله ﷺ"]],"q":"ما منزلة السنة في التشريع بالنسبة إلى كتاب الله؟"},{"id":"u83_3","label":"أقسام أفعال النبي","segs":[["matn","إنّ مما يتصل بالسُّنن أَفعالُ النَّبيّ ﷺ الاختيارية الصَّالحة للاقتداء، وهي ثلاثة: مباحٌ، ومستحبّ، وواجبٌ"]],"q":"ما أقسام أفعال النبي ﷺ الاختيارية الصالحة للاقتداء؟"},{"id":"u83_4","label":"حكم الاقتداء بأفعاله","segs":[["matn","والصَّحيحُ أَنَّ بكلِّ ما عُلِم وقوعُه من الأفعال على وجهٍ يُقْتَدى به في إيقاعِهِ على تلك الصِّفةِ من الوجوبِ والنَّدبِ والإباحة، حتى يقوم به دليل الخصوص، وما لا نعلم على أَي صفةٍ فعله ﷺ فيُعتقد فيه الإباحة؛ لتيقّنها"]],"q":"ما الصحيح في الاقتداء بأفعاله ﷺ، وما حكم ما لم تُعلم صفته؟"}],"sup":"المبحث الرَّابع حجية خبر الآحاد وأقسامه"},{"id":"u84","title":"الباب الثَّالث الإجماع (١)","group":"الباب الثَّالث الإجماع","units":[{"id":"u84_1","label":"تعريف الإجماع","segs":[["matn","الإجماع لغةً: العزم واصطلاحاً: هو اتفاق المجتهدين من أُمَّة سيدنا محمد ﷺ في عصر من العصور على أمر شرعيّ"]],"q":"ما تعريف الإجماع لغةً واصطلاحًا؟"},{"id":"u84_2","label":"الإجماع العزيمة ووجهاه","segs":[["matn","الأول: عزيمة، ولها وجهان: ١. التَّكلُّم بما يوجب اتفاق الكلّ على الحكم، ٢. الشُّروع في الفعل إن كان ذلك الشَّيء من باب الفعل"]],"q":"ما الإجماع العزيمة، وما وجهاه؟"},{"id":"u84_3","label":"الإجماع الرخصة ووجهاه","segs":[["matn","الثاني: رخصة، ولها وجهان: ١. التَّكلم بما يوجب اتفاق بعضهم على الحكم، وسكوت الباقين منهم بعد بلوغ الخبر إليهم، ٢. الشُّروع في الفعل من بعضهم إن كان ذلك الشَّيء من باب الفعل، وسكوت الباقين ويُسمَّى هذا النَّوع إجماعاً سكوتياً"]],"q":"ما الإجماع الرخصة، وما وجهاه، وبمَ يسمّى؟"},{"id":"u84_4","label":"حكم الإجماع السكوتي","segs":[["matn","وهذا الإجماع السُّكوتي من الأدلّةِ القطعيّةِ عند أكثر الحنفيّة، وإنَّما لا يكفر جاحدُه؛ لما فيه من توهم الشُّبهة."]],"q":"ما حكم الإجماع السكوتي عند أكثر الحنفية، ولماذا لا يكفر جاحده؟"},{"id":"u84_5","label":"سند الإجماع","segs":[["matn","فكلُّ مسألة مجمع عليها فهي مستفادة من الكتاب أو السُّنة أو من قياس متأصل فيهما، وهذا الأصل من الكتاب أو السُّنة ما يقال له: سند الإجماع."]],"q":"ما سند الإجماع؟"}]},{"id":"u84b","title":"الباب الثَّالث الإجماع (٢)","group":"الباب الثَّالث الإجماع","units":[{"id":"u84_6","label":"فائدة الإجماع","segs":[["matn","إنَّ الحكم الثَّابت من الكتاب أو السُّنة أو القياس إن كان ظنياً، فإنَّه يصبح بالإجماع قطعياً، أما إن كان الحكم قطعياً من قبل، فإنَّ الإجماع يزيد في قطعيته."]],"q":"ما فائدة الإجماع في الحكم الظني والقطعي؟"},{"id":"u84_7","label":"شروط أهل الإجماع","segs":[["matn","يشترط في الإجماع ومن ينعقد بهم الإجماع ما يلي: ١. أن يكون مجتهداً صالحاً؛ ٢. أن لا يكون فيه هوى؛ ٣. أن لا يكون فاسقاً؛ ٤. أن يكون الإجماع من كلِّ المجتهدين"]],"q":"ما الشروط فيمن ينعقد بهم الإجماع؟"},{"id":"u84_8","label":"ما ليس بشرط في الإجماع","segs":[["matn","ويخرج من أهلية وشروط الإجماع: ١. أن يكون في الصَّحابة رضي الله عنهم. ٢. أن يكون في العترة؛ ٣. أن يكون في أهل المدينة. ٤. أن ينقرض العصر بموت جميع المجتهدين ٥. أن لا يسبقه اختلاف سابق في المسألة"]],"q":"ما الأمور التي ليست بشرط في الإجماع؟"},{"id":"u84_9","label":"مراتب الإجماع","segs":[["matn","المرتبة الأقوى: أقواها مرتبة وأعلاها درجة الإجماع القولي والفعلي للصَّحابة، والمرتبة الوسطى: الإجماع السُّكوتي أوسطها درجة بالنِّسبة إلى صحابة رسول الله ﷺ، والمرتبة الدُّنيا: تنحصر في إجماع مَن بعد الصَّحابة رضي الله عنهم من فقهاء كلّ عصر"]],"q":"ما مراتب الإجماع الثلاث؟"},{"id":"u84_10","label":"مكانة الإجماع بحسب نقله","segs":[["matn","مكانة الإجماع كدليل شرعي تتوقف على درجة سند وصولها إلينا تماماً كمكانة السُّنة النبوية، فما وصل منهما إلينا بالتَّواتر كان قطعياً، وما وصل إلينا بسند موثوق به دون التَّواتر كان ظنياً، وما وصل إلينا بسند ضعيف غير موثوق به فلا وزن له"]],"q":"بمَ تتحدد مكانة الإجماع بحسب سند نقله إلينا؟"}]},{"id":"u86","title":"المطلب الأول: تعريفه وحجيته","group":"الباب الرابع القياس","units":[{"id":"u86_1","label":"تعريف القياس","segs":[["matn","القياس: لغةً: تقدير الشَّيء على مثاله واصطلاحاً: ١.تقديرُ الفرع بالأصل في الحكم والعلَّة. ٢.إبانة مثل حكم أحد المذكورين مثل علَّته في الآخر"]],"q":"ما تعريف القياس لغةً واصطلاحًا؟"},{"id":"u86_2","label":"القياس مظهر لا مثبت","segs":[["matn","لأنَّ القياس مُظهر لا مُثبت؛ لأنَّ المُثبت هو الله تعالى، أمَّا القياس ففعل القائس، وهو تبيين وإعلام أنَّ حكم الله تعالى كذا وعلَّته كذا"]],"q":"هل القياس مثبت للحكم أم مظهر له؟ ولماذا؟"}]},{"id":"u87","title":"المطلب الثَّاني: شروط القياس","group":"الباب الرابع القياس","units":[{"id":"u87_1","label":"شروط القياس الخمسة","segs":[["matn","شروط القياس: ١.أن لا يكون الأصل مخصوصاً ٢.أن لا يكون حكم الأصل معدولاً به عن القياس ٣.أن يتعدّى الحكم الشَّرعي الثَّابت بالنَّصِّ بعينه إلى فرع هو نظيره ولا نصّ فيه، ٤.أن يبقى الحكم في الأصل بعد التَّعليل على ما كان قبله ٥.أن لا يكون التَّعليل متضمناً إبطال شيءٍ مـن ألفـاظ المنصـوص"]],"q":"ما شروط القياس الخمسة؟"},{"id":"u87_2","label":"شروط تعدية الحكم","segs":[["matn","ويتضمن هذا الشَّرط أربعة شروط، أ.أن يكون الحكم شرعياً لا لغوياً ب.أن يُعدّى الحكمُ بعينه بلا تغيير، ج.أن يكون الفرعُ نظيراً للأصل لا أدون منه د.أن لا يوجد في الفرع نصٌ"]],"q":"ما الشروط الأربعة التي يتضمنها شرط تعدية الحكم؟"},{"id":"u87_3","label":"معنى الأصل المخصوص","segs":[["matn","أن لا يكون الأصل مخصوصاً: أي بسبب آخر يدلُّ على اختصاص المَقيس عليه بحكمه، وهو ما يُعبِّر عنه الفقهاء بحكاية حال: أي حكم خاصّ بهذه الحادثة لا يُقاس عليه غيرُه"]],"q":"ما معنى ألّا يكون الأصل مخصوصًا؟"}]},{"id":"u88","title":"المطلب الثالث: العلَّة (١)","group":"الباب الرابع القياس","units":[{"id":"u88_1","label":"أركان القياس الأربعة","segs":[["matn","١.الأصل المقيس عليه: وهو ما يبتنى عليه غـيره ٢.الفرع المقيس: وهو ما يبتني على غيره ٣.حكم الأصل: وهو ما أفاده الـنَّصّ كتابـاً كـان أو سُـنَّة أو إجماعـاً، ٤.العلَّة: وهي الوصفُ الجامعُ بين الأصل والفرع"]],"q":"ما أركان القياس الأربعة مع تعريف كل منها؟"},{"id":"u88_2","label":"تعريف العلة","segs":[["matn","العلَّة: الوصفُ الصَّالحُ المؤثِّرُ في ثبوت الحكم في الأصل متى وُجد مثلُه في الفرع يثبت مثل ذلك الحكم فيه قياساً عليه."]],"q":"ما تعريف العلة في القياس؟"},{"id":"u88_3","label":"علل الشرع أمارات","segs":[["matn","علـل الشَّرـع: أمـارات ومُعرِّفـات للحكـم، وعلامة عليه، والموجب الحقيقي هو الله تعالى."]],"q":"ما حقيقة علل الشرع، ومن الموجب الحقيقي؟"},{"id":"u88_4","label":"صور الوصف ركن العلة","segs":[["matn","والوصف الذي هو ركن العلَّة له صور: ١.أن يكون لازماً ٢.أن يكون عارضاً ٣.أن يكون اسماً ٤.أن يكون جلياً ٥.أن يكون خفيّاً ٦.أن يكون حكماً شرعياً ٧.أن يكون فرداً ٨.أن يكون عدداً ٩.أن يكون منصوصاً ١٠.أن يكون غير منصوص"]],"q":"ما صور الوصف الذي هو ركن العلة؟"},{"id":"u88_5","label":"مسالك العلة الصحيحة","segs":[["matn","مسالك العلَّة: هي الطُّرق الدَّالة على كون الوصف المعين علَّة للحكم. والمسالك الصَّحيحة عند الحنفية ثلاثة: النَّص والإجماع والمناسبة"]],"q":"ما مسالك العلة، وما الصحيح منها عند الحنفية؟"},{"id":"u88_6","label":"مسلك الإجماع","segs":[["matn","الإجماع: وهو اتفاق المجتهدين في عصر من الأعصار على كون وصف معيّن علَّة للحكـم المعيّن"]],"q":"ما مسلك الإجماع في إثبات العلة؟"},{"id":"u88_7","label":"مسلك النص وقسماه","segs":[["matn","النَّصُّ: بأن تكون العِلِّية ثابتة بالنَّص، وهو قسمان: أولهما: الصَّريح: وهو ما دلَّ بوضعه على العِلَّة، ثانيهما: الإيماء: وهو أن يلزم من مدلول اللفظ العِلَّة"]],"q":"ما مسلك النص في إثبات العلة، وما قسماه؟"}]},{"id":"u88b","title":"المطلب الثالث: العلَّة (٢)","group":"الباب الرابع القياس","units":[{"id":"u88_8","label":"مراتب النص الصريح","segs":[["matn","المرتبة الأولى: التَّعليل بلفظ؛ المرتبة الثَّانية: التَّعليل بحرف؛ المرتبة الثَّالثة: ذكر الفاء من الشَّارع؛ المرتبة الرَّابعة: ذكر الفاء في لفظ الرَّاوي"]],"q":"ما مراتب النص الصريح في التعليل؟"},{"id":"u88_9","label":"وجوه الإيماء","segs":[["matn","الإيماء: الأولى: أن يقترن وصف بحكم غير مناسب معه إن لم يكن علَّة؛ الثَّانية: أن يقترن وصف بحكم مناسب معه فيفيد العِلِّيَّة الثَّالثة: أن يُفَرِّق بين شيئين في الحكم بصيغة صفة"]],"q":"ما وجوه الإيماء في إثبات العلة؟"},{"id":"u88_10","label":"الملاءمة: المناسبة والموافقة","segs":[["matn","المناسبة بشرط الملائمة: ١.المناسبة: هي مناسبته للحكم بأن يصحّ إضافة الحكم إليه، ولا يكون نابياً عنه ٢.الموافقةُ: بأن يكون الوصفُ على موافقةِ العلّل المنقولةِ عن رسول الله ﷺ وعن السَّلفِ مـن الصَّحابة والتَّابعين رضي الله عنهم"]],"q":"ما معنى المناسبة والموافقة في شرط الملاءمة؟"},{"id":"u88_11","label":"عدالة الوصف والمؤثر","segs":[["matn","عدالة الوصف: وهي تثبت بالتَّأثير، والوصفُ المؤثّر: ما جُعِلَ له أَثرٌ في الشَّرع، بأن يكون لجـنس ذلك الوصف تأثيرٌ في إثباتِ جنس ذلك الحكم في مورد الشرع"]],"q":"بمَ تثبت عدالة الوصف، وما الوصف المؤثر؟"},{"id":"u88_12","label":"أقسام الوصف المؤثر","segs":[["matn","١.أن يظهرَ تأثيرُ عين الوصف في عين ذلك الحكم ٢.أن يظهر تـأثير عـين الوصـف في جـنس ذلـك الحكـم ٣.أن يؤثر جنس الوصف في عين ذلك الحكم: وهو الذي خصّوه بالملائم، ٤.ما ظهر أثر جنس الوصف في جنس ذلك الحكم"]],"q":"ما أقسام الوصف المؤثر الأربعة؟"},{"id":"u88_13","label":"الفرق بين العلة والحكمة","segs":[["matn","أما الحكمة فهي الفائدة التي يتوقع حصولها من العمل بالحكم: أي الباعث على تشريع الحكم من المصلحة التي قصدها الشارع، فتبيّن بما ذكرنا أنَّ الحكم لا يتغير بتغير الحكمة، وإنَّما يتغيَّر بتغير العلّة"]],"q":"ما الحكمة، وهل يتغير الحكم بتغيرها أم بتغير العلة؟"}]},{"id":"u89","title":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس","group":"الباب الرابع القياس","units":[{"id":"u89_1","label":"موانع العلة الأربعة","segs":[["matn","موانع العلَّة أربعة، وهي: ١.مانع يمنع انعقاد العلَّة ٢.مانع يمنع تمام العلَّة ٣.مانع يمنع ابتداء الحكم ٤.مانع يمنع دوام الحكم"]],"q":"ما موانع العلة الأربعة؟"},{"id":"u89_2","label":"وجوه دفع القياس الثمانية","segs":[["matn","وجوه دفع القياس ثمانية، وهي: ١.الممانعة ٢. القول بموجب العلَّة ٣. القلب ٤. العكس ٥. فساد الوضع ٦. الفرق ٧. النَّقض ٨. المعارضة"]],"q":"ما وجوه دفع القياس الثمانية؟"},{"id":"u89_3","label":"الممانعة ونوعاها","segs":[["matn","الممانعة: مفاعلة من المنع، وهي عدم قَبول دليل المُستدل كلاً أو بعضاً، وهي نوعان: أ.منع العلَّة ب.منع الحكم"]],"q":"ما تعريف الممانعة، وما نوعاها؟"},{"id":"u89_4","label":"القول بموجب العلة","segs":[["matn","القول بموجب العلَّة: وهو تسليم العلَّة، وبيان أنَّ حكمها غير ما ادَّعاه المُستدلّ"]],"q":"ما تعريف القول بموجب العلة؟"},{"id":"u89_5","label":"القلب ونوعاه","segs":[["matn","القلب: وهو نوعان: أ. قلب العلَّة حكماً والحكمُ علةً ب. قلب علَّة الحكم علّة لضدّ ذلك الحكم"]],"q":"ما نوعا القلب في دفع القياس؟"},{"id":"u89_6","label":"العكس وفساد الوضع وغيرهما","segs":[["matn","العكس: هو ردُّ الحكم على خلاف سننه الأول، فساد الوضع: هو بيان كون العلَّة غير صالح للحكم الفرق: هو بيان الفرق بين الأمرين النَّقض: هو بيان تَخَلُّف الحكم عن العلَّة المعارضة: هي إقامةُ الدَّليل على خلافِ ما أقام عليه الخصم الدَّليل"]],"q":"ما تعريف العكس وفساد الوضع والفرق والنقض والمعارضة؟"}]},{"id":"u90","title":"المطلب الرَّابع: الاستحسان","group":"الباب الرابع القياس","units":[{"id":"u90_1","label":"القياس الجلي والخفي","segs":[["matn","يقسم القياس من حيث جلاؤه وغموضُه إلى قسمين: ١.القياسُ الجليّ: وهو ما تبادرت أفهام المجتهدين إلى وجهِـهِ وعلَّتـه، ٢.القياسُ الخفيّ: وهو ما لا تنتقل أفهام المجتهدين إلى وجهه وعلَّته إلا بعد البحث والتَّأمل، ويُسمّونه الاستحسان."]],"q":"ما قسما القياس من حيث الجلاء والخفاء؟"},{"id":"u90_2","label":"تعريف الاستحسان","segs":[["matn","والاستحسان لغةً: وجود الشَّيء حسناً، واصطلاحاً: عدول المجتهد عن حكم كلِّي إلى حكـم اسـتثنائي بـدليل انقـدح في عقله رَجَّح له هذا العدول، أو عدولُ المجتهد عن قياس جلي إلى قياس خفي"]],"q":"ما تعريف الاستحسان لغةً واصطلاحًا؟"},{"id":"u90_3","label":"أنواع الاستحسان الثلاثة","segs":[["matn","وأنواع الاستحسان ثلاثة: أوَّلاً: استحسانٌ بأصول الاستنباط ثانياً: استحسان بأصول البناء ثالثاً: استحسان بأصول الإفتاء"]],"q":"ما أنواع الاستحسان الثلاثة؟"},{"id":"u90_4","label":"الاستحسان بأصول الاستنباط","segs":[["matn","استحسانٌ بأصول الاستنباط: ويُعبّر عنه بأنَّه تخصيص الحكم بالنَّص مع وجود العلَّة، وهو أن يثبت نصٌّ عن الشَّارع يوجب ردّ القياس"]],"q":"ما الاستحسان بأصول الاستنباط؟"},{"id":"u90_5","label":"الاستحسان بأصول البناء","segs":[["matn","استحسان بأصول البناء: ويعبر عن هذا بأن يكون فرع يتجاذبه أصلان، يأخذ الشّبه من كل واحد منهما، فيجب إلحاقه بأحدهما دون الآخر ؛ لدلالة توجبه"]],"q":"ما الاستحسان بأصول البناء؟"},{"id":"u90_6","label":"الاستحسان بأصول الإفتاء","segs":[["matn","استحسان بأصول الإفتاء: فالاستحسان فيه أن يترك العمل بظاهر الحكم إلى غيره؛ لوجود ضرورة أو عرف أو حرج أو غيرها. ويُعبَّر عنه بأنَّه تخصيصُ الحكم بالرَّسم مع وجود العلَّة"]],"q":"ما الاستحسان بأصول الإفتاء؟"},{"id":"u90_7","label":"علة تقديم الاستحسان","segs":[["matn","وتقديم الاستحسان علىٰ القياس؛ لقوة أثره؛ لأنَّ المدار علىٰ قوة التَّأثير وضعفه لا علىٰ الظُّهور والخفاء."]],"q":"لماذا يُقدَّم الاستحسان على القياس؟"}]},{"id":"u91","title":"الباب الخامس الأحكام","group":"الباب الخامس الأحكام","units":[{"id":"u91_1","label":"ما يفتقر إليه الحكم","segs":[["matn","إنَّ الحكم يفتقر إلىٰ الحاكم، وهو الله تعالىٰ لا العقل، وإلىٰ المحكوم به، وهو فعل المكلف، وإلىٰ المحكوم عليه، وهو المكلَّف"]],"q":"ما الأمور التي يفتقر إليها الحكم؟"}]},{"id":"u93","title":"المطلب الأول: تعريفه","group":"الباب الخامس الأحكام","units":[{"id":"u93_1","label":"الحكم عند الأصوليين","segs":[["matn","الحكم: عند الأصوليين: هو خطاب الشَّارع المتعلّق بأفعال المكلفين طلباً أو تخييراً أو وضعاً"]],"q":"ما تعريف الحكم عند الأصوليين؟"},{"id":"u93_2","label":"الطلب والتخيير والوضع","segs":[["matn","فالطَّلب يشمل الفرضية والوجوب والسُّنّة والكراهة والحرام. والتَّخيير يشمل المباح. والوضع يكون فيما إن تعلَّق بكون الشَّيء سبباً، أو شرطاً، أو مانعاً، أو صحيحاً، أو فاسداً"]],"q":"ما الذي يشمله الطلب والتخيير والوضع في الحكم؟"},{"id":"u93_3","label":"الحكم عند الفقهاء","segs":[["matn","وعند الفقهاء: هو الأثرُ الحاصلُ من خطابِ الله تعالى، ويُقال عنها: الوجوب، والنَّدب، والحرمة، والكراهة، والإباحة"]],"q":"ما تعريف الحكم عند الفقهاء؟"}],"sup":"المبحث الأول الحكم"},{"id":"u94","title":"المطلب الثَّاني: أقسامُ الحكم (١)","group":"الباب الخامس الأحكام","units":[{"id":"u94_1","label":"تعريف الحكم الوضعي","segs":[["matn","الحكمُ الوضعيّ: وهو أن يكون حكمٌ بتعلّق شيءٍ بشيءٍ آخر فإن كان المتعلّق داخلاً في الشَّيء، فهو الرُّكن، وإن لم يكن المتعلِّق داخلاً في الشَّيء، فهو العلَّة والسَّبب والشَّرط والعلامة"]],"q":"ما تعريف الحكم الوضعي، وما الركن والعلة والسبب والشرط فيه؟"},{"id":"u94_2","label":"تعريف العلة وتمامها","segs":[["matn","العلَّة: وهي ما كان مؤثِّراً في الشَّيء، أو هي عبارةٌ عَمّا يُضاف إليه وجوبُ الحكم ابتداءً. وتكون العلَّةُ الشَّرعيّة الحقيقيّة تامّةً بثلاثةِ أشياء: الاسم والمعنىٰ والحكم."]],"q":"ما تعريف العلة، وبمَ تكون العلة الشرعية تامة؟"},{"id":"u94_3","label":"معنى الاسم والمعنى والحكم","segs":[["matn","فالاسم: أن تكون العلَّة في الشَّرع وضع لهذا الحكم، والمعنىٰ: أن تكون العلَّةُ مؤثِّرةً في الحكم، والحكم: أن لا يتراخىٰ الحكم عن العلَّة،"]],"q":"ما معنى الاسم والمعنى والحكم في العلة؟"},{"id":"u94_4","label":"أقسام العلة السبعة","segs":[["matn","للعلَّة سبعة أقسام: ١. علّةٌ اسماً وحكماً ومعنى ٢. علّةٌ اسماً ومعنى لا حكماً ٣. علَّةٌ اسماً وحكماً لا معنى ٤. علّةٌ اسماً لا معنىً ولا حكماً ٥. علَّة معنى وحكماً لا اسماً ٦. علّةٌ لها شبهٌ بالسَّبب ٧. وصفٌ له شبهة العلل"]],"q":"ما أقسام العلة السبعة؟"},{"id":"u94_5","label":"تعريف السبب","segs":[["matn","السبب: وهو ما يكون طريقاً إلىٰ الحكم من غير تأثير، يعني أنَّ السَّبب مفض إلىٰ الحكم وطريق إليه لا مؤثر فيه"]],"q":"ما تعريف السبب؟"},{"id":"u94_6","label":"أنواع السبب الثلاثة","segs":[["matn","والسَّبب ثلاثة أنواع: ١. سببُ حقيقيّ: وهو ما يكون طريقاً إلى الحكم من غير أن يُضاف إليه وجوبٌ ولا وجودٌ ولا يُعقل فيه معاني العلل، ٢. سبب مجازي ٣. سببٌ في معنى العلَّة"]],"q":"ما أنواع السبب الثلاثة؟"},{"id":"u94_7","label":"تعريف الشرط","segs":[["matn","الشَّرط: وهو ما يتوقَّف عليه وجود الشَّيء وليس بمؤثر فيه، أو ما يتعلَّق به الوجود لا الوجوب"]],"q":"ما تعريف الشرط؟"},{"id":"u94_8","label":"أنواع الشرط","segs":[["matn","والشَّرط أنواع: ١. شرطٌ محضٌ: وهو الذي يتوقّف انعقاد العلَّة علىٰ وجوده، ٢. شرط في حكم العلَّة ٣. شرطٌ له حكم السَّبب ٤. شرطٌ مجازاً: أي اسماً لا حكماً"]],"q":"ما أنواع الشرط؟"}],"sup":"المبحث الأول الحكم"},{"id":"u94b","title":"المطلب الثَّاني: أقسامُ الحكم (٢)","group":"الباب الخامس الأحكام","units":[{"id":"u94_9","label":"تعريف العلامة","segs":[["matn","العلامة: وهي ما لا يتوقف عليه الشَّيء، ولكن دلَّ علىٰ وجوده، أو ما جُعل عَلَماً علىٰ الوجود من غير أن يتعلَّق به وجوب ولا وجود."]],"q":"ما تعريف العلامة؟"},{"id":"u94_10","label":"تعريف الحكم التكليفي","segs":[["matn","الحكمُ التَّكليفيُّ: وهو ما لا يكون حُكماً بتعلّق شيءٍ بشيءٍ آخر، كأن يكون أثراً لفعل المكلّف أو يكون صفةً لفعل المكلّف"]],"q":"ما تعريف الحكم التكليفي؟"},{"id":"u94_11","label":"الصحيح والباطل والفاسد","segs":[["matn","الصَّحيح: بأن يقع الفعل بحيث يوصل إلىٰ المقصود الدُّنيوي، ويقال له: ما يكون مشروعاً بأصله ووصفه. الباطل: ما لا يكون مشروعاً بأصله ولا بوصفه الفاسد: ما يكون مشروعاً بأصله دون وصفه."]],"q":"ما تعريف الصحيح والباطل والفاسد؟"},{"id":"u94_12","label":"الانعقاد والنفاذ واللزوم","segs":[["matn","الانعقاد: وهو ارتباطُ أجزاء التَّصرف «الإيجاب والقبول» شرعاً، النَّفاذ: وهو ترتب الأثر علىٰ التَّصرّف اللزوم: أن يكون التصرّف بحيث لا يمكن رفعه"]],"q":"ما تعريف الانعقاد والنفاذ واللزوم؟"},{"id":"u94_13","label":"العزيمة والرخصة","segs":[["matn","أقسام المقاصد الأُخروية: أولاً: أن يكون حكماً أصلياً، ويُسمّى عزيمة؛ لأنَّه غيرُ مبنيّ علىٰ أعذار العباد، ثانياً: أن لا يكون حكماً أصلياً، ويُسمّى رخصةً، لكونه مبنيّاً علىٰ أعذار العباد"]],"q":"ما العزيمة والرخصة من أقسام المقاصد الأخروية؟"},{"id":"u94_14","label":"الفرض وحكمه","segs":[["matn","الفرض: أن يكون الفعل أولىٰ من التَّرك مع منع التَّرك بدليل بقطعي. وحكمه: لازمٌ علماً وعملاً حتىٰ يكفر جاحده"]],"q":"ما تعريف الفرض، وما حكمه؟"},{"id":"u94_15","label":"الواجب وحكمه","segs":[["matn","الواجب: أن يكون الفعل أولىٰ من الترك مع منع التَّرك بدليل ظني. لكن يلزم العمل بموجبه للدَّلائل الدَّالّة علىٰ وجوب اتّباع الظَّنّ، فجاحدُه لا يكفر"]],"q":"ما تعريف الواجب، وما حكمه؟"},{"id":"u94_16","label":"السنة وسنن الهدى","segs":[["matn","السُّنَّة: أن يكون الفعل أولىٰ من التَّرك بلا منع التَّرك، وهي نوعان: أ. سننُ الهُدى: إن كان الفعلُ طريقةً مسلوكةً في الدِّين وحكمُها: أنَّ تركَها يوجب إساءةً وكراهيةً"]],"q":"ما تعريف السنة، وما سنن الهدى وحكمها؟"}],"sup":"المبحث الأول الحكم"},{"id":"u94c","title":"المطلب الثَّاني: أقسامُ الحكم (٣)","group":"الباب الخامس الأحكام","units":[{"id":"u94_17","label":"سنن الزوائد","segs":[["matn","ب. سنن الزَّوائد: ما كانت المواظبة من النَّبي ﷺ مع التَّرك أحياناً علىٰ سبيل العادة، وحكمها: أنَّ تركها لا يوجب إساءة وكراهة."]],"q":"ما سنن الزوائد، وما حكمها؟"},{"id":"u94_18","label":"الحرام وحكمه","segs":[["matn","الحرام: أن يكون التَّركُ أَوْلَىٰ من الفعل مع منع الفعل. وحكمُه: أنَّه يُعاقب علىٰ فعلِه."]],"q":"ما تعريف الحرام، وما حكمه؟"},{"id":"u94_19","label":"المكروه ونوعاه","segs":[["matn","المكروه: أن يكون التَّرك أولىٰ من الفعل، بلا منع الفعل، وهو نوعان: أ. مكروهٌ كراهة تنزيه: وهو إلىٰ الحلِّ أقرب اتفاقاً ب. مكروهٌ كراهة تحريم: وهو إلىٰ الحرمة أقرب علىٰ المختار"]],"q":"ما تعريف المكروه، وما نوعاه؟"},{"id":"u94_20","label":"المباح","segs":[["matn","المباح: أن لا يكون الفعل والترك أحدهما أولىٰ من الآخر، والمباح قابل أن يصير طاعةً بالنية الحسنة وأن يصير معصية بالنية القبيحة"]],"q":"ما تعريف المباح، وهل يصير طاعة أو معصية؟"},{"id":"u94_21","label":"الرخصة الحقيقية وحالتاها","segs":[["matn","ما يطلق عليه الرُّخصة حقيقة، وله حالتان: وهو ما استبيح مع قيام دليل المحرم ووجود حكم الحرمة، ومن أمثلتها: إجراء كلمة الكفر مكرهاً بالقتل أو القطع وهو ما استبيح مع قيام دليل المحرّم دون حكم الحرمة، ومثالها: إفطار المسافر"]],"q":"ما الرخصة الحقيقية، وما حالتاها مع التمثيل؟"},{"id":"u94_22","label":"الرخصة المجازية وحالتاها","segs":[["matn","ما يطلق عليه الرُّخصة مجازاً، وله حالتان: أ. الأقرب للمجازية: وهو ما وضع عنّا من الإصر والأغلال، ب. الأقرب للحقيقة، وهو ما سقط مع كونه مشروعاً في الجملة،"]],"q":"ما الرخصة المجازية، وما حالتاها؟"}],"sup":"المبحث الأول الحكم"},{"id":"u95","title":"المبحث الثاني المحكوم به","group":"الباب الخامس الأحكام","units":[{"id":"u95_1","label":"تعريف المحكوم به","segs":[["matn","المحكوم به: وهو الفعلُ الذي تعلَّق به خطاب الشَّارع: أي فعل المكلَّف من صلاةٍ وصومٍ ووفاءٍ بالعقود وغيرها."]],"q":"ما تعريف المحكوم به؟"},{"id":"u95_2","label":"تعريف حقوق الله تعالى","segs":[["matn","أولاً: حقوق الله تعالى، وهو ما يتعلَّق به النَّفع العام من غير اختصاص بأحدٍ"]],"q":"ما تعريف حقوق الله تعالى؟"},{"id":"u95_3","label":"أنواع حقوق الله الثمانية","segs":[["matn","حقوق الله تعالى: وهي ثمانية: ١. عباداتٌ خالصةٌ: كالإيمان وفروعه ٢. عبادةٌ فيها مؤنة: كصدقةِ الفطر ٣. مؤنةٌ فيها عقوبة: كالخراج ٤. مؤنةٌ فيها عبادة: كالعُشر في الأرض العشرية علىٰ المسلم ٥. حقٌّ قائمٌ بنفسه ٦. عقوباتٌ كاملة: كالحدود. ٧. عقوباتٌ قاصرة: كحرمان الميراث بالقتل ٨. حقوقٌ دائرةٌ بين العبادةِ والعقوبة: كالكفّارات"]],"q":"ما أنواع حقوق الله تعالى الثمانية مع التمثيل؟"},{"id":"u95_4","label":"تعريف حقوق العباد","segs":[["matn","ثانياً: حقوق العباد: وهو ما يتعلّق به مصلحة خاصّة"]],"q":"ما تعريف حقوق العباد؟"},{"id":"u95_5","label":"ما اجتمع فيه الحقان","segs":[["matn","ثالثاً: ما اجتمع فيه الحقَّان، وحقّ الله تعالى غالب: كحدّ القذف رابعاً: ما اجتمع فيه الحقّان، وحَقُّ العبد غالب: كالقصاص"]],"q":"ما حكم ما اجتمع فيه الحقان مع التمثيل؟"}]},{"id":"u96","title":"المبحث الثَّالث الحاكم","group":"الباب الخامس الأحكام","units":[{"id":"u96_1","label":"محل الخلاف في الحاكم","segs":[["matn","اتفق علماء المسلمين علىٰ أنَّ الأحكام الشَّرعية لجميع أفعال المكلفين مصدرها الله تعالىٰ وإنَّما اختلفوا في أنَّ أحكامَ الله تعالىٰ في أفعال المكلفين هل يُمكن للعقل أن يعرفَها من غير وساطة رُسل الله تعالىٰ وكُتبه أم لا يمكنه ذلك؟"]],"q":"ما محل الاتفاق والخلاف في الحاكم؟"},{"id":"u96_2","label":"مذهب المعتزلة في العقل","segs":[["matn","الأول: قول المعتزلة: العقل علَّة موجبة لما استحسنه ومحرِّمة لما استقبحه، فوق العلل الشَّرعية"]],"q":"ما مذهب المعتزلة في العقل؟"},{"id":"u96_3","label":"مذهب الأشعرية في العقل","segs":[["matn","الثَّاني: قول الأشعرية: لا عبرة للعقل دون السَّمع، وإذا جاء السَّمع فله العبرة دون العقل"]],"q":"ما مذهب الأشعرية في العقل؟"},{"id":"u96_4","label":"مذهب الماتريدية المعتمد","segs":[["matn","الثَّالث: قول الماتريدية: وهو الصَّحيح المعتمد ؛ لأنَّه توسّط بين مذهب المعتزلة والأشاعرة؛ إذ الشَّرعُ مبنيٌّ علىٰ العقل"]],"q":"ما مذهب الماتريدية في العقل، ولماذا اعتُمد؟"},{"id":"u96_5","label":"من لم تبلغه الدعوة","segs":[["matn","فإنَّ مَن لم تبلغه الدَّعوة غير مكلَّف بمجرد العقل، فإذا لم يعتقد إيماناً ولا كفراً كان معذوراً إذا لم يصادف مدّةً يتمكَّن فيها من التَّأمُّل والاستدلال وأمّا إذا أعانه الله تعالىٰ بالتَّجربة وأمهله لدرك العواقب لم يكن معذوراً وإن لم تبلغه الدَّعوة"]],"q":"ما حكم من لم تبلغه الدعوة؟"},{"id":"u96_6","label":"صحة إيمان الصبي","segs":[["matn","ويصحُّ إيمانُ الصَّبيِّ وإن لم يكن مُكلَّفاً به؛ لأنَّ الوجوبَ بالخطاب، وهو ساقطٌ عنه"]],"q":"هل يصح إيمان الصبي؟ ولماذا؟"}]},{"id":"u97","title":"المبحث الرَّابع المحكوم عليه","group":"الباب الخامس الأحكام","units":[{"id":"u97_1","label":"تعريف المحكوم عليه","segs":[["matn","المحكوم عليه: وهو المكلَّفُ الذي تعلَّق حكم الشَّارع بفعله، ولا بُدّ من أهليته للحكم، وهي لا تثبت إلا بالعقل وأقام الشَّرع البلوغ مقام اعتدال العقل."]],"q":"ما تعريف المحكوم عليه، وبمَ تثبت أهليته؟"},{"id":"u97_2","label":"تعريف الأهلية","segs":[["matn","والأهلية له لغةً: الصَّلاحيّة له. واصطلاحاً: عبارةٌ عن صلاحيته لوجوب الحقوقِ المشروعةِ له وعليه"]],"q":"ما تعريف الأهلية لغةً واصطلاحًا؟"}]},{"id":"u98","title":"المطلب الأول: مراحل الأهلية","group":"الباب الخامس الأحكام","units":[{"id":"u98_1","label":"أهلية الوجوب ونوعاها","segs":[["matn","الأوّل: أهليّة الوجوب: وهي صلاحية لوجوب الحقوق الشَّرعية عليه، وهي نوعان: ١. أهلية الوجوب له: وتكون في مرحلة الحمل ٢. أهليّة وجوب له وعليه: وتكون في مرحلةِ عدم التَّمييز للصَّغير"]],"q":"ما أهلية الوجوب، وما نوعاها؟"},{"id":"u98_2","label":"ثمرة الوجوب على الصبي","segs":[["matn","وتظهر ثمرة الوجوب له وعليه في الأداء علىٰ التَّفصيل الآتي: أ. إن كان من حقوق العباد، فيلزم وصيّ الصَّبيّ الغرامات ب. إن كان من العقوبات، فلا يجب على الصَّبي العقوبة ج. إنَّ كان من حقوق الله تعالى، فلا يجب على الصَّبيّ العبادات الخالصة ويجب على وصيّ الصَّبيِّ أداء العُشر والخراج"]],"q":"كيف تظهر ثمرة الوجوب للصبي وعليه في الأداء؟"},{"id":"u98_3","label":"أهلية الأداء ونوعاها","segs":[["matn","الثَّاني: أهلية أداء: وهي صلاحيةٌ لصدور الفعل منه علىٰ وجهٍ يعتدُّ به شرعاً، وهي نوعان: ١. أهلية قاصرة: وتكون في مرحلةِ الصَّبيِّ المميز أو المعتوه ٢. أهلية كاملة: وتكون في مرحلة البلوغ إلىٰ الموت"]],"q":"ما أهلية الأداء، وما نوعاها؟"},{"id":"u98_4","label":"القاصرة في حقوق الله","segs":[["matn","أ. إن كان حقّاً لله تعالى، وله ثلاثة صور: ـ إن كان حسناً: كالإيمان، فيصحّ من الصَّبي بلا لزوم أدائه ـ إن كان قبيحاً: كالردَّة، فإنَّه لا يجعل عفواً، فتصحّ ردّته في حقّ أحكام الدُّنيا والآخرة ـ إن كان متردّداً بين الحُسن في زمان والقُبح في زمان: كالصَّلاة والصَّوم فيصحّ من الصَّبيّ أداؤه من غير لزوم عهدة وضمان"]],"q":"ما صور الأهلية القاصرة في حقوق الله تعالى؟"},{"id":"u98_5","label":"القاصرة في حقوق العباد","segs":[["matn","ب. إن كان حقاً لغير الله تعالى، وله ثلاثة صور: ـ إن كان نفعاً محضاً: كقَبول الهبة والصَّدقة، فإنَّه يصحّ مباشرة الصَّبيِّ له من غير رضا الوليّ وإذنه. ـ إن كان ضرراً محضاً، بحيث لا يشوبه نفعٌ دنيويّ: كالطَّلاق والوصيّة ودفع الصَّدقة والهبة والقرض، فإنَّه يبطل أصلاً ـ إن كان دائراً بين النَّفع والضَّرر: كالبيع ونحوه، فإنَّه يملكه برأيّ الولي"]],"q":"ما صور الأهلية القاصرة في حقوق غير الله تعالى؟"}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u99","title":"المطلب الثَّاني: عوارض الأهلية (١)","group":"الباب الخامس الأحكام","units":[{"id":"u99_1","label":"العوارض السماوية","segs":[["matn","والعوارض نوعان: الأول: العارض السَّماوي، وهي: ١. الصِّغر ٢.الجنون ٣.العته ٤.النِّسيان ٥.النَّوم ٦.الإغماء ٧.المرض ٨.الحيض والنِّفاس ٩.الموت"]],"q":"ما العوارض السماوية؟"},{"id":"u99_2","label":"الجنون وحكمه","segs":[["matn","٢.الجنون: وهو آفةٌ بالدِّماغ بحيث يبعث على أفعال خلاف مقتضى العقل من غير ضعف في أعضائه. ويأخذ أحكام الصَّبي غير المميز من سقوط العبادات ولزوم حقوق العباد وعدم وجوب العقوبات"]],"q":"ما تعريف الجنون، وما حكمه؟"},{"id":"u99_3","label":"حد امتداد الجنون","segs":[["matn","لكن في العبادات إذا لم يمتد الجنون أُلحق بالنَّوم استحساناً وحدُّ الامتداد في الصَّلاة أن يزيدَ على يوم وليلة، وفي الصَّوم باستغراق الشَّهر، وفي الزَّكاة باستغراق الحول."]],"q":"متى يُلحق الجنون بالنوم، وما حد امتداده؟"},{"id":"u99_4","label":"العته وحكمه","segs":[["matn","٣.العته: وهو آفةٌ توجب خللاً في العقل، فيصير صاحبه مختلط الكلام يُشَبَّه بعض كلامه بكلام العقلاء، وبعضه بكلام المجانين. وحكمه: حكم الصَّبي المميز في كلِّ الأحكام"]],"q":"ما تعريف العته، وما حكمه؟"},{"id":"u99_5","label":"النسيان وحكمه","segs":[["matn","٤.النِّسيان: وهو جهلٌ ضروريّ بما كان يعلمه بغير آفةٍ مع علمِه بأمورٍ كثيرة. وحكمُه: أنَّه لا يُنافي الوجوب في حقّ الله تعالى لكن النِّسيان إذا كان غالباً كما في الصَّوم، والتَّسمية في الذَّبيحة، والسَّلام في الصَّلاة، فإنَّه يكون عفواً ولا يجعل النِّسيان عذراً في حقوق العباد"]],"q":"ما تعريف النسيان، وما حكمه؟"}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u99b","title":"المطلب الثَّاني: عوارض الأهلية (٢)","group":"الباب الخامس الأحكام","units":[{"id":"u99_6","label":"النوم وحكمه","segs":[["matn","٥.النَّوم: وهو فترةٌ طبعيّةٌ تَحْدُثُ للإنسان بلا اختيار. وحكمه: أنَّه عجزٌ عن استعمال القدرة يوجب تأخير الخطاب، ولا يمنع الوجوب ونومُه يُنافي الاختيار أصلاً"]],"q":"ما تعريف النوم، وما حكمه؟"},{"id":"u99_7","label":"الإغماء وحكمه","segs":[["matn","٦.الإغماء: وهو نوعُ مرض يُضْعِفُ القوى ولا يُزيل العقل. وحكمه: كالنَّوم حتى بطلت عباراتُه، بل الإغماء أشدُّ من النَّوم في فوت الاختيار وإن امتدّ الإغماء يسقط به الأداء؛ للحرج"]],"q":"ما تعريف الإغماء، وما حكمه؟"},{"id":"u99_8","label":"المرض ومرض الموت","segs":[["matn","٧.المرض: وهو حالةٌ للبدن يزول بها اعتدال الطَّبيعة. وحكمُه: أنَّه سبب للتَّخفيف في الأحكام الشَّرعية وأمّا مرضُ الموت فيتعلَّق بالأمور الماليّة، فيكون سبباً لتعلّق حقّ الورثة بثلثي التَّركة ويتعلَّق حقّ الغريم بكلّ التَّركة"]],"q":"ما تعريف المرض، وما حكمه وحكم مرض الموت؟"},{"id":"u99_9","label":"الحيض والنفاس","segs":[["matn","٨.الحيض والنِّفاس: وهما سواء في الأحكام؛ إذ لا يعدمان أَهلية الوجوب ولا الأداء، لكن الطَّهارة عنهما لصلاةٍ شرطٌ ويُقْضَى الصَّوم؛ لعدم الحرج في قضائه، بخلاف الصَّلاة، فإنَّها لا تُقْضَى لكثرتها"]],"q":"ما حكم الحيض والنفاس في الأهلية والقضاء؟"},{"id":"u99_10","label":"الموت وحكمه","segs":[["matn","٩.الموت: وهو عرض لا يصحّ معه إحساسٌ معقب للحياة. ففي حقوق الله تعالى، فالموت ينافي الأهلية في أحكام الدُّنيا ممَّا فيه تكليف"]],"q":"ما تعريف الموت، وما حكمه في حقوق الله تعالى؟"}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u100","title":"الثَّاني: العارض المكتسب (١)","group":"الباب الخامس الأحكام","units":[{"id":"u100_1","label":"تعريف العارض المكتسب","segs":[["matn","العارض المكتسب: وهي التي تكون لكسبِ العبادِ مدخل فيها بمباشرة الأسباب كالسُّكر، أو بالتَّقاعد عن المُزيل: كالجهل"]],"q":"ما تعريف العارض المكتسب مع التمثيل؟"},{"id":"u100_2","label":"الجهل البسيط والمركب","segs":[["matn","١.الجهل: وله حالتان: أ.بسيط: وهو عدمُ العلم عمّا من شأنه أن يكون عالماً ب.مركب: وهو اعتقادُ جازم غير مطابق للواقع مع اعتقاد مطابقته"]],"q":"ما حالتا الجهل؟"},{"id":"u100_3","label":"أنواع الجهل الثلاثة","segs":[["matn","وللجهل ثلاثة أنواع: أ.جهل لا يصلح عذراً في الآخرة ب.جهل يصلح شبهة: كالجهل في مواضع الاجتهاد الصَّحيح أو في موضع الشُّبهة ج.جهل يصلح عذراً؛ كالجهل في دار الحرب من مسلم لم يهاجر إلينا"]],"q":"ما أنواع الجهل الثلاثة مع التمثيل؟"},{"id":"u100_4","label":"تعريف السكر","segs":[["matn","٢.السُّكر: وهو سرورٌ يغلبُ على العقل بمباشرةِ بعض الأسبابِ الموجبةِ له، فيمنع الإنسان عن العمل بموجب عقله من غير أن يزيلَه."]],"q":"ما تعريف السكر؟"},{"id":"u100_5","label":"السفه وحكمه","segs":[["matn","٣.السَّفه: وهو العملُ بخلاف مقتضى العقل والشَّرع، وإن كان الفعل في أصله مشروعاً وحكمُه: أَنَّه لا يوجب خللاً في الأهلية، ولا يمنع شيئاً من أحكامِ الشَّرعِ من الوجوبِ له وعليه ويكون سبباً للحجر عليه عند أبي يوسف ومحمد رضي الله عنهم، ولا يحجر عليه عند أبي حنيفة رضي الله عنه"]],"q":"ما تعريف السفه، وما حكمه؟"},{"id":"u100_6","label":"السفر وحكمه","segs":[["matn","٤.السَّفر: وهو الخروج المديد عن موضع الإقامة على قصد السَّير، وأدناه ثلاثة أيام. وحكمه: أنَّه لا ينافي أهلية الخطاب؛ لبقاء العقل والقدرة البدنية، لكنَّه من أسباب التَّخفيف بنفسه مطلقاً"]],"q":"ما تعريف السفر، وما حكمه؟"}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u100b","title":"الثَّاني: العارض المكتسب (٢)","group":"الباب الخامس الأحكام","units":[{"id":"u100_7","label":"الخطأ وأحكامه","segs":[["matn","٥.الخطأ: وهو وقوع الشَّيء على خلاف ما أُريد. ومن أحكامه: أ.يُسقط حقّ الله جل جلاله إذا حصل عن اجتهاد ب. يَدرأ الكفَّارة والحدّ والقصاص ج. يوجب الضَّمان في حقوق العباد"]],"q":"ما تعريف الخطأ، وما أحكامه؟"},{"id":"u100_8","label":"الإكراه وأنواعه","segs":[["matn","الإكراه: وهو حملُ الغير على ما لا يرضاه. وأنواع الإكراه: أ.أن يعدم الرِّضا ويفسد الاختيار، ويكون في الإكراه الملجئ ب.أن يعدم الرِّضا ولا يفسد الاختيار ج.أن لا يعدم الرِّضا ولا يفسد الاختيار"]],"q":"ما تعريف الإكراه، وما أنواعه؟"},{"id":"u100_9","label":"حكم الإكراه","segs":[["matn","الإكراه: وحكمه: أنَّه لا ينافي الخطاب والأهلية بجميع أنواعه؛ لبقاء العقل والبلوغ الذي عليه مدار الخطاب والأهلية، فهو مترددٌ بين فرض وحظر وإباحة ورخصة"]],"q":"ما حكم الإكراه؟ ولماذا؟"},{"id":"u100_10","label":"الهزل وشرطه","segs":[["matn","الهزل: وهو أن يرادَ بالشَّيءِ غيرُ ما وُضع له ولا مناسبة بينهما والهازل لا يختار الحكم ولا يرضى به، ولكنَّه يرضى بمباشرة السَّبب وشرط الهزل المعتبر أن يكون صريحاً مشروطاً باللسان"]],"q":"ما تعريف الهزل، وما شرطه المعتبر؟"},{"id":"u100_11","label":"أثر الهزل في التصرفات","segs":[["matn","التَّصرفات التي يجري فيها الهزل ثلاثة أنواع: أ.في العقائد، والهزل فيها باطل ب. في الإخبارات، والهزل يبطلُها مطلقاً ج.في الإنشاءات ـ أن يكون الهزلُ فيما لا مال فيه: كالطَّلاق واليمين، فذلك صحيح، والهزل باطل"]],"q":"ما أنواع التصرفات التي يجري فيها الهزل، وما أثره فيها؟"}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u103","title":"المبحث الأول الاجتهاد","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u103_1","label":"تعريف الاجتهاد","segs":[["matn","الاجتهاد: لغةً: قيل: تحمُّل الجَهَد ـ بالفتح ـ: أي المشقّة، وقيل: استفراغُ الجُهد ـ بالضم ـ: أي الطَّاقة. واصطلاحاً: استفراغُ الفقيه الوسعَ لتحصيل ظنٍّ بحكم شرعيٍّ فرعيٍّ."]],"q":"ما تعريف الاجتهاد لغةً واصطلاحًا؟"},{"id":"u103_2","label":"شروط المجتهد المطلق","segs":[["matn","ثانياً: شرط المجتهد المطلق: أن يحوي علوماً ثلاثة: ١.أن يعرف آيات القرآن المتعلِّقة بمعرفة الأحكام ٢.معرفةُ السُّنّة المتعلِّقة بالأحكام وطريق وصولها إلينا ٣. معرفةُ القياسِ بشرائطِه وأركانِه وأقسامِه المقبولة والمردودة، ويستلزمُ معرفة المسائل المجمع عليها"]],"q":"ما شروط المجتهد المطلق؟"},{"id":"u103_3","label":"الحق واحد عند الله","segs":[["matn","ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد عامّة الفقهاء قالوا: المجتهدُ يُخطِئ ويُصيب، والحقُّ عند الله واحد، وإن لم يتعيَّن لنا فهو عند الله متعيِّن"]],"q":"هل الحق عند الله واحد أم متعدد؟"},{"id":"u103_4","label":"واجب غير المجتهد","segs":[["matn","أقلّ ما يجب على غير المجتهد في باب الاجتهاد أن يتخيَّر لدينه مجتهداً يراه الأعلم والأورع، فينصاع لفتياه. وأمّا تتبّعه الرُّخص من أقوال كلِّ إمام، والأخذ بما يوافق الهوى من آراء الأئمّة، فليسا إلا تشهّياً محضاً"]],"q":"ما أقل ما يجب على غير المجتهد في باب الاجتهاد؟"}]},{"id":"u104","title":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u104_1","label":"لا تعارض في نفس الأمر","segs":[["matn","إنَّ هذه الشَّريعةَ الغراءَ صادرةٌ عن إلهٍ واحدٍ ونبيٍّ واحدٍ، فلا شَكَّ في خلوها عن التَّعارضِ والتَّناقضِ في نفسِ الأمر، وإنَّما هو أَمْرٌ في الظَّاهر"]],"q":"هل يقع التعارض في الشريعة في نفس الأمر؟ ولماذا؟"},{"id":"u104_2","label":"تعريف التعارض","segs":[["matn","فالتَّعارضُ لغةً: التَّمانع والتَّدافع والتَّنافر واصطلاحاً: وهو تقابلُ المتساويين قوّةً حقيقة مع اتحاد النِّسبة بين الحجج"]],"q":"ما تعريف التعارض لغةً واصطلاحًا؟"},{"id":"u104_3","label":"تعريف الترجيح","segs":[["matn","والتَّرجيح لغة: جعلُ الشَّيءِ راجحاً: أي فاضلاً زائداً واصطلاحاً: بيانُ الرُّجحان: أي القوّة التي لأحد المتعارضين على الآخر."]],"q":"ما تعريف الترجيح لغةً واصطلاحًا؟"},{"id":"u104_4","label":"ركن التعارض","segs":[["matn","ويثبت التَّعارض عند وجود ركنه وشرطه: فركنه: هو المماثلةُ والمساواةُ بين الدَّليلين في الثُّبوت والقوة"]],"q":"ما ركن التعارض؟"},{"id":"u104_5","label":"شرط التعارض","segs":[["matn","وشرطُه: هو المخالفةُ بين حكميهما، إمّا من حيث تضاد الحكم: كالحلّ والحرمة، أو من حيث التَّنافي: كالنَّفي والإثبات، لكن التَّضاد والتَّنافي لا يثبت إلا عند اتحاد المحلّ والزَّمان والجهة"]],"q":"ما شرط التعارض؟"}]},{"id":"u105","title":"المطلب الأول: الحكم عند وقوع التَّعارض","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u105_1","label":"التعارض بين النصوص","segs":[["matn","أوّلاً: إن وقع بين الآيتين يصار إلى السُّنة ثانياً: إذا وقع بين السُّنتين يصار إلى أَقوال علماءِ الصَّحابة رضي الله عنهم وإن لم نقف على قول للصَّحابة رضي الله عنهم ننتقل إلى القياس، فيرجح به"]],"q":"ما الحكم إذا وقع التعارض بين الآيتين أو بين السنتين؟"},{"id":"u105_2","label":"التعارض بين قياسين وبعده","segs":[["matn","ثالثاً: إذا وقع بين قياسين، فإن أَمكن ترجيح أحدهما عُمِل به، وإن لم يمكن ترجيح أحدهما على الآخر فيَعمل المجتهدُ بأيِّهما شاء بشهادةِ قلبه وعند العجز عن المصير إلى دليل، يجب تقرير الأصول، وهو إبقاء ما كان على ما كان"]],"q":"ما الحكم إذا وقع التعارض بين قياسين، وعند العجز عن الدليل؟"}],"sup":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج"},{"id":"u106","title":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u106_1","label":"وجوه التخلص من المعارضة","segs":[["matn","وجوهُ التَّخلص من المعارضة: ١.بيانُ عدم وجودِ ركن المعارضة أو شرطها لعدم معادلة المعارض ٢.اختلاف الحكم بأن يكون أحدُهما حكم الدُّنيا والآخرُ حكم الآخرة ٣.اختلاف الحال بحمل أَحدِهما على حال والآخر على أُخرى ٤ .اختلاف الزَّمان"]],"q":"ما وجوه التخلص من المعارضة؟"},{"id":"u106_2","label":"وجها اختلاف الزمان","segs":[["matn","اختلاف الزَّمان: وله وجهان: أ.صريحاً: كآيتي العدَّة ب.دلالة: كما في تعارض الحاظر والمبيح فيجعل الحاظر متأخراً؛ تقليلاً لتغيير الأمر الأصلي."]],"q":"ما وجها اختلاف الزمان في التخلص من المعارضة؟"},{"id":"u106_3","label":"ما لا يرجح به","segs":[["matn","ولا ترجيح بكثرةِ الرُّواةِ ولا بالذُّكورةِ ولا بالحرية وبذلك لا يترجَّح عددٌ على عددٍ بعد أن كان في درجةِ الآحاد"]],"q":"ما الذي لا يُرجَّح به بين الأخبار؟"}],"sup":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج"},{"id":"u107","title":"المطلب الثَّالث: التَّعارضُ بين قياسين","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u107_1","label":"وجوه الترجيح بين قياسين","segs":[["matn","التَّعارضُ بين قياسين: ١.التَّرجيحُ بقوّةِ أَثَر الوَصْف ٢. التَّرجيح بقُوّة ثبات الوصفِ على الحكم الذي يَشْهَد الوصف بثبوته ٣.التَّرجيحُ بكثرةِ أُصول الوصف ٤ .التَّرجيحُ بعدم الحكم عند عدم الوصف، ووجوده عند وجوده"]],"q":"ما وجوه الترجيح بين قياسين؟"},{"id":"u107_2","label":"تعارض ضربي الترجيح","segs":[["matn","٥.إذا تعارض ضَربا ترجيح، فالرّجحانُ بما هو في الذَّات أَولى بالاعتبار من الرُّجحان بما هو في الحال"]],"q":"ما الحكم إذا تعارض ضربا ترجيح؟"},{"id":"u107_3","label":"زيادة أحد الخبرين","segs":[["matn","وإذا كان في أحدِ الخبرين زيادةٌ لم تكن في الآخر، والرَّاوي واحدٌ، يؤخذ بالمُثبت للزِّيادة وإذا اختلف الرَّاوي جُعِل الخبر كالخبرين وعُمِل بهما"]],"q":"ما الحكم إذا كان في أحد الخبرين زيادة؟"}],"sup":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج"}]};
